import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, transfersAvailable } from "@/lib/registrar";
import { SANDBOX } from "@/lib/sandbox";
import { Icon } from "@/components/nx/Icon";
import { DomainsAurora } from "@/components/nx/DomainsAurora";
import { DomainSearchPanel } from "@/components/customer/domains/DomainSearchPanel";
import { DomainsTable, type DomainRow } from "@/components/customer/domains/DomainsTable";
import { DomainsTabs } from "@/components/customer/domains/DomainsTabs";
import { DomainTransferInWizard } from "@/components/customer/DomainTransferInWizard";
import { DomainIdeaGenerator } from "@/components/customer/DomainIdeaGenerator";
import { findDomainInboxPlan } from "@/lib/domain-inbox-email";

export const dynamic = "force-dynamic";

function daysUntil(d: Date): number {
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

/* ── stat tile ──────────────────────────────────────────────────────────
   The concept's tile: a tinted, bordered icon square (not a solid brand
   plate), the figure beside it, label under, and an optional coloured
   delta line. Local to this page — it is this page's own look, not a
   change to the shared StatCard every other page uses. */
const TILE = {
  blue:  { ink: "text-[#7fb0ff]" },
  green: { ink: "text-emerald-400" },
  amber: { ink: "text-orange-400" },
} as const;

function Stat({
  icon, tone, value, label, foot,
}: {
  icon: string; tone: keyof typeof TILE; value: string; label: string; foot?: React.ReactNode;
}) {
  const t = TILE[tone];
  return (
    <div className="flex min-w-0 items-start gap-3.5 rounded-[15px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.6))] px-4 py-3.5">
      <Icon name={icon} size={24} tone="inherit" className={"mt-0.5 flex-none " + t.ink} />
      <span className="flex min-w-0 flex-col">
        <span className="num text-[23px] font-bold leading-none text-white">{value}</span>
        <span className="mt-1 text-[13px] text-tx-dim">{label}</span>
        {foot}
      </span>
    </div>
  );
}

const HELP_LINKS = [
  { icon: "file", t: "Domain Setup Guide", s: "Step-by-step instructions", href: "/help" },
  { icon: "transfer2", t: "Transfer a Domain", s: "Move from another registrar", href: "/dashboard/domains/transfer" },
  { icon: "server2", t: "DNS Management", s: "Manage your DNS records", href: "/tools" },
  { icon: "chatdots", t: "Contact Support", s: "Our team is here to help", href: "/dashboard/support" },
];

export default async function DomainsPage() {
  const user = await requireUser();
  const configured = registrarConfigured();
  const canTransfer = transfersAvailable();

  const domains = await db.domain.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  // Real per-domain inbox state — a domain only counts as "Email: Enabled"
  // when it actually has a live mailbox, never just because a subscription
  // row exists.
  const emailSubs = domains.length
    ? await db.emailSubscription.findMany({
        where: { userId: user.id, domainName: { in: domains.map((d) => d.name) }, status: { not: "CANCELLED" } },
        select: { domainName: true, mailboxes: { select: { status: true } } },
      })
    : [];
  const emailByDomain = new Map(
    emailSubs.map((s) => [s.domainName, s.mailboxes.some((m) => m.status === "ACTIVE")])
  );

  const inboxPlan = await findDomainInboxPlan();

  const active = domains.filter((d) => d.status === "ACTIVE").length;
  const expiringSoon = domains.filter(
    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
  );
  const soonestExpiry = expiringSoon
    .map((d) => daysUntil(d.expiresAt!))
    .sort((a, b) => a - b)[0];
  const pendingTransfers = domains.filter((d) => d.status === "TRANSFER_PENDING").length;
  const now = new Date();
  const registeredThisMonth = domains.filter(
    (d) => d.createdAt.getUTCFullYear() === now.getUTCFullYear() && d.createdAt.getUTCMonth() === now.getUTCMonth()
  ).length;

  const rows: DomainRow[] = domains.map((d) => ({
    id: d.id,
    name: d.name,
    status: d.status,
    expiresAtIso: d.expiresAt ? d.expiresAt.toISOString() : null,
    autoRenew: d.autoRenew,
    // An empty nameserver list means the domain sits on the registrar's own
    // DNS, which is what the product calls Nxeon DNS; anything set is custom.
    nameserverLabel: d.nameservers.length === 0 ? "Nxeon DNS" : "Custom",
    emailEnabled: emailByDomain.get(d.name) ?? false,
    priceCents: d.priceCents,
  }));

  return (
    <>
      <DomainsAurora />

      {/* relative + z-1: DomainsAurora is a POSITIONED (fixed, z-0) layer, so
          it paints above ordinary static content — its opaque bottom band was
          slicing the top off anything that landed in the first 460px, like the
          sidebar's first card. Lifting the content onto its own layer fixes it. */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col">
        {/* ── hero ─────────────────────────────────────────────────────── */}
        <header className="relative min-h-[210px] pt-1">
          {/* eslint-disable-next-line @next/next/no-img-element -- static hero art, not an optimizable content image */}
          <img
            src="/nx/hero-domains-globe.webp"
            alt=""
            aria-hidden
            className="nx-breathe pointer-events-none absolute right-[13%] top-0 hidden h-[184px] w-auto object-contain lg:block xl:h-[204px]"
          />
          <span aria-hidden className="absolute right-0 top-7 hidden flex-col items-end gap-[5px] xl:flex">
            {["BUILD", "BRANDS", "WITHOUT", "LIMITS"].map((l) => (
              <span key={l} className="text-[11px] font-semibold uppercase tracking-[0.3em] text-[#9d8bff]">{l}</span>
            ))}
          </span>

          <div className="relative max-w-[620px] pt-6">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.24em] text-[#f21cff]">Network</span>
            <h1 className="mt-2 text-[38px] font-extrabold leading-[1.04] tracking-[-0.035em] text-white sm:text-[42px]">
              Domains
            </h1>
            <p className="mt-2 text-[14.5px] text-tx-dim">
              Register, transfer and manage your domains all in one place.
            </p>
          </div>
        </header>

        <DomainsTabs
            search={<DomainSearchPanel configured={configured} sandbox={SANDBOX} />}
            mine={
              <div className="space-y-5">
                {domains.length > 0 && (
                  <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                    <Stat
                      icon="globe2" tone="blue" value={String(domains.length)} label="Total domains"
                      foot={registeredThisMonth > 0
                        ? <span className="mt-1 text-[12px] font-semibold text-emerald-400">↑ {registeredThisMonth} this month</span>
                        : undefined}
                    />
                    <Stat icon="checkcircle" tone="green" value={String(active)} label="Active domains" />
                    <Stat
                      icon="warntriangle" tone={expiringSoon.length > 0 ? "amber" : "blue"}
                      value={String(expiringSoon.length)} label="Expiring soon"
                      foot={expiringSoon.length > 0
                        ? <span className="mt-1 text-[12px] font-semibold text-red-400">in {soonestExpiry} day{soonestExpiry === 1 ? "" : "s"}</span>
                        : undefined}
                    />
                    <Stat icon="transfer2" tone="blue" value={String(pendingTransfers)} label="Pending transfers" />
                  </div>
                )}
                <DomainsTable rows={rows} configured={configured} />
              </div>
            }
            transfers={
              canTransfer ? (
                <DomainTransferInWizard initialDomain="" balanceCents={user.balanceCents} />
              ) : (
                <div className="rounded-[16px] border border-rim-hi bg-well px-5 py-10 text-center text-sm text-tx-dim">
                  Domain transfers aren&apos;t available yet — they light up once the registrar is
                  configured. Domains already on your account stay manageable in the meantime.
                </div>
              )
            }
            ideas={<DomainIdeaGenerator configured={configured} />}
            sidebar={
              <>
                {/* nx-dark-island — a fixed purple promo gradient with
                    text-white/NN opacity text, same fix as the search card
                    above: without it, light mode's opacity-decoupling rule
                    retargets that text for a light page and it disappears
                    into this one, which stayed dark on purpose. */}
                <div className="nx-dark-island rounded-[16px] border border-[#7b3fef]/45 bg-[linear-gradient(150deg,rgba(103,50,224,.55),rgba(37,63,190,.35)_60%,rgba(20,40,120,.3))] p-5">
                  <span className="grid h-12 w-12 place-items-center rounded-[13px] border border-white/20 bg-white/10">
                    <Icon name="gift" size={21} tone="inherit" className="text-fuchsia-300" />
                  </span>
                  <h3 className="mt-3.5 text-[17px] font-extrabold text-white">Free Business Email</h3>
                  <p className="mt-1.5 text-[13px] leading-relaxed text-white/75">
                    Get a free email inbox with every domain registration
                    {inboxPlan ? ` — ${inboxPlan.mailboxes} mailbox, ${inboxPlan.storageGB} GB` : ""}.
                  </p>
                  <ul className="mt-4 space-y-2.5">
                    {["Professional email address", "Webmail access", "Spam protection"].map((f) => (
                      <li key={f} className="flex items-center gap-2.5 text-[13.5px] text-white/95">
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#e879f9" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="flex-none">
                          <path d="M20 6 9 17l-5-5" />
                        </svg>
                        {f}
                      </li>
                    ))}
                  </ul>
                </div>

                {canTransfer && (
                  <Link
                    href="/dashboard/domains/transfer"
                    className="nx-dark-island flex items-start gap-3.5 rounded-[16px] border border-rim-hi bg-[linear-gradient(140deg,rgba(30,50,130,.4),rgba(6,14,38,.6))] p-4 transition hover:border-brand-400/50"
                  >
                    <span className="grid h-12 w-12 flex-none place-items-center rounded-[13px] border border-[#3d7bff]/35 bg-[#3d7bff]/12">
                      <Icon name="transfer2" size={20} tone="inherit" className="text-[#7fb0ff]" />
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-2">
                        <span className="text-[16px] font-extrabold text-white">Transfer a domain</span>
                        <span className="ml-auto text-tx-dim">→</span>
                      </span>
                      <span className="mt-1 block text-[12.5px] leading-snug text-tx-dim">
                        Move your domain to Nxeon and start managing it today.
                      </span>
                    </span>
                  </Link>
                )}

                <div className="nx-dark-island rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(9,20,45,.5),rgba(2,7,20,.6))] p-5">
                  <h3 className="text-[17px] font-extrabold text-white">Need Help?</h3>
                  <div className="mt-3.5 space-y-1">
                    {HELP_LINKS.map((item) => (
                      <Link
                        key={item.t}
                        href={item.href}
                        className="group flex items-center gap-3 rounded-[11px] px-1.5 py-2 transition hover:bg-white/[0.04]"
                      >
                        <Icon name={item.icon} size={17} tone="inherit" className="flex-none text-[#7fb0ff]" />
                        <span className="min-w-0 flex-1">
                          <span className="block text-[13.5px] font-semibold text-white">{item.t}</span>
                          <span className="block text-[11.5px] text-tx-faint">{item.s}</span>
                        </span>
                        <Icon name="external" size={14} tone="inherit" className="flex-none text-[#5b8fd8] opacity-70 group-hover:opacity-100" />
                      </Link>
                    ))}
                  </div>
                </div>
              </>
            }
        />
      </div>
    </>
  );
}

import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import {
  getDnsHosts,
  registrarConfigured,
  registrarSafeMessage,
  transferStatusLabel,
  type DnsHost,
} from "@/lib/registrar";
import { transferChargeCents } from "@/lib/domain-transfer";
import { TransferInStatusCard } from "@/components/customer/DomainTransferIn";
import { getRegistrarLock, listRedirects } from "@/lib/actions-domains-dns";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageShell } from "@/components/nx/PageShell";
import { DomainsAurora } from "@/components/nx/DomainsAurora";
import type { QuickServer } from "@/components/customer/DnsQuickSetup";
import { DomainDetailShell } from "@/components/customer/DomainDetailShell";
import { type ChecklistItem } from "@/components/customer/DomainChecklist";
import { DomainTour } from "@/components/nx/tour/DomainTour";

export const dynamic = "force-dynamic";

function daysUntil(d: Date): number {
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
  if (!d) return { text: "—", tone: "slate" };
  const days = daysUntil(d);
  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
  if (days === 0) return { text: "expires today", tone: "red" };
  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
  return { text: `in ${days} days`, tone: "green" };
}

const STATUS_META: Record<string, { label: string; tone: "amber" | "rose" | "cyan" | "mint" | "slate" }> = {
  ACTIVE: { label: "Active", tone: "mint" },
  PENDING: { label: "Pending", tone: "amber" },
  TRANSFER_PENDING: { label: "Transfer pending", tone: "amber" },
  EXPIRED: { label: "Expired", tone: "rose" },
  FAILED: { label: "Failed", tone: "rose" },
  TRANSFER_FAILED: { label: "Transfer failed", tone: "rose" },
};

export default async function DomainPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ new?: string }>;
}) {
  const { id } = await params;
  const { new: justRegistered } = await searchParams;
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();

  const publicIp = process.env.PUBLIC_IP ?? "";
  const active = domain.status === "ACTIVE";
  const showGoLive = justRegistered === "1" && active;

  // The user's own servers — targets for the "point at my server" preset.
  const servers = await db.server.findMany({
    where: { userId: domain.userId },
    include: { dedicatedIp: true, node: { select: { publicIp: true } } },
    orderBy: { createdAt: "desc" },
  });
  const quickServers: QuickServer[] = servers.map((s) => ({
    id: s.id,
    label: s.label || s.name || s.hostname,
    ip: s.dedicatedIp?.address || s.node?.publicIp || "",
  }));

  let dnsHosts: DnsHost[] | null = null;
  let dnsError: string | null = null;
  if (active && registrarConfigured()) {
    try {
      dnsHosts = await getDnsHosts(domain.name);
    } catch (e) {
      dnsError = registrarSafeMessage(e);
    }
  }

  const [lockView, redirectsView] = await Promise.all([
    getRegistrarLock(domain.id),
    listRedirects(domain.id),
  ]);

  let hostingFromCents: number | null = null;
  let vpsFromCents: number | null = null;
  if (showGoLive) {
    const [hostingPlans, vpsPlans] = await Promise.all([
      db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }),
      db.plan.findMany({ where: { active: true }, select: { priceCents: true } }),
    ]);
    hostingFromCents = hostingPlans.length ? Math.min(...hostingPlans.map((p) => p.priceCents)) : null;
    vpsFromCents = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
  }

  // ----- Setup checklist -----
  const knownIps = new Set<string>([publicIp, ...quickServers.map((s) => s.ip)].filter(Boolean));
  const apexRecords = (dnsHosts ?? []).filter((h) => h.name === "@" || h.name === "www");
  const pointedAtServer = apexRecords.some(
    (h) => (h.type === "A" && knownIps.has(h.address)) || h.type === "CNAME" || h.type === "ALIAS"
  );
  const emailConfigured = (dnsHosts ?? []).some((h) => h.type === "MX");
  const checklist: ChecklistItem[] = [
    {
      label: domain.isTransferIn ? "Domain transferred in" : "Domain registered",
      done: active,
      hint: domain.isTransferIn
        ? "The transfer is still running — approve the confirmation email from your old registrar."
        : "Registration is still processing.",
    },
    { label: "Pointed at a server", done: pointedAtServer, hint: "Use Quick setup → “Point this domain at my server”." },
    { label: "Email configured", done: emailConfigured, hint: "Add MX records via Quick setup → Google Workspace, or your mail host." },
    { label: "WHOIS privacy on", done: domain.whoisPrivacy, hint: "Turn on WHOIS privacy under Security." },
    { label: "Auto-renew on", done: domain.autoRenew, hint: "Enable auto-renew so it never lapses." },
  ];

  const meta = STATUS_META[domain.status] ?? { label: domain.status, tone: "slate" as const };
  const term = domainTerm(domain.termYears);
  const renewPerYearCents = (domain as any).renewPriceCents ?? domain.priceCents;
  const renewTotal = domainTermPriceCents(renewPerYearCents, term.years);
  const exp = expiryNote(domain.expiresAt);

  return (
    <>
      <DomainsAurora />

      {/* No full-screen Provisioning takeover here, deliberately — domain
          registration is synchronous, so there is no real multi-step progress
          to show, and every one of PENDING/FAILED/just-registered already has
          its own honest, inline banner below (the amber "being processed"
          note, the red failure card, the green go-live card). A takeover
          screen on top of those said the same thing twice and buried the
          hero's own aurora under an opaque panel. */}
      {domain.status === "PENDING" && <AutoRefresh />}

      <PageShell eyebrow="NETWORK" title={domain.name} sub="Domain management" wisp={false}>
        <div className="-mt-2 mb-1 flex flex-wrap items-center gap-3">
          <span className={"nx-tag nx-tag-" + meta.tone + (meta.tone === "amber" ? " nx-tag-pulse" : "")}>
            <span className="nx-tag-dot" aria-hidden />
            {meta.label}
          </span>
          <span className="text-[12.5px] text-tx-dim">
            Registered {domain.registeredAt ? domain.registeredAt.toISOString().slice(0, 10) : "—"}
            {domain.expiresAt && <> · Renews {domain.expiresAt.toISOString().slice(0, 10)} ({exp.text})</>}
          </span>
          <Link href="/dashboard/domains" className="btn-ghost ml-auto text-xs">← All domains</Link>
        </div>

        {showGoLive && (
          <div className="card mb-5 border-emerald-500/30 bg-emerald-500/[0.06]">
            <div className="flex items-start gap-3">
              <span className="mt-0.5 flex h-9 w-9 flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M20 6 9 17l-5-5" />
                </svg>
              </span>
              <div>
                <h2 className="font-semibold text-white">{domain.name} is registered</h2>
                <p className="mt-1 text-sm text-slate-300">
                  Now let&apos;s get something live on it. Add hosting or a VPS and point this domain at it in a
                  couple of clicks.
                </p>
              </div>
            </div>
            <div className="mt-4 grid gap-4 sm:grid-cols-2">
              <div className="rounded-xl border border-rim-hi bg-well p-4">
                <p className="text-sm font-semibold text-white">Shared Web Hosting</p>
                <p className="mt-1 text-xs leading-relaxed text-tx-dim">
                  PHP, MySQL, free SSL, and a free bundled mailbox on this domain.
                  {hostingFromCents !== null && <> Plans from {fmtMoney(hostingFromCents)}/mo — first month free.</>}
                </p>
                <Link href="/web-hosting" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See hosting plans</Link>
              </div>
              <div className="rounded-xl border border-rim-hi bg-well p-4">
                <p className="text-sm font-semibold text-white">NVMe VPS</p>
                <p className="mt-1 text-xs leading-relaxed text-tx-dim">
                  Full root access for apps, game servers, or anything shared hosting can&apos;t run.
                  {vpsFromCents !== null && <> Plans from {fmtMoney(vpsFromCents)}/mo.</>}
                </p>
                <Link href="/vps" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See VPS plans</Link>
              </div>
            </div>
          </div>
        )}

        {domain.status === "FAILED" && (
          <div className="card mb-5 border-red-500/30 text-sm text-red-300">
            Registration failed{domain.error ? `: ${domain.error}` : "."} You were refunded — try again or
            contact support.
          </div>
        )}

        {domain.status === "PENDING" && !domain.isTransferIn && (
          <div className="card mb-5 border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-200">
            Registration is being processed. This page refreshes automatically — it usually completes within
            a minute.
          </div>
        )}

        {domain.isTransferIn && (domain.status === "TRANSFER_PENDING" || domain.status === "TRANSFER_FAILED") && (
          <div className="mb-5">
            <TransferInStatusCard
              domainId={domain.id}
              domainName={domain.name}
              status={domain.status}
              transferStatus={domain.transferStatus}
              transferStatusLabel={domain.transferStatus ? transferStatusLabel(domain.transferStatus) : null}
              transferEmail={domain.transferEmail}
              transferStartedAt={domain.transferStartedAt ? domain.transferStartedAt.toISOString() : null}
              priceCents={transferChargeCents(domain.priceCents)}
              error={domain.error}
            />
          </div>
        )}

        <div className="mb-2 flex justify-end">
          <DomainTour domain={domain} />
        </div>
        <DomainDetailShell
          domain={{
            id: domain.id,
            name: domain.name,
            status: domain.status,
            registeredAt: domain.registeredAt ? domain.registeredAt.toISOString() : null,
            expiresAt: domain.expiresAt ? domain.expiresAt.toISOString() : null,
            autoRenew: domain.autoRenew,
            whoisPrivacy: domain.whoisPrivacy,
            nameservers: domain.nameservers,
          }}
          active={active}
          statusLabel={meta.label}
          statusTone={meta.tone}
          exp={exp}
          term={term}
          renewPerYearCents={renewPerYearCents}
          renewTotal={renewTotal}
          checklist={checklist}
          registrarConfigured={registrarConfigured()}
          quickServers={quickServers}
          publicIp={publicIp}
          dnsHosts={dnsHosts}
          dnsError={dnsError}
          redirectsView={redirectsView}
          lockView={lockView}
          hasEpp={!!domain.transferEpp}
        />
      </PageShell>
    </>
  );
}
import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, checkDomains } from "@/lib/registrar";
import { SANDBOX } from "@/lib/sandbox";
import { db } from "@/lib/db";
import { fmtMoney } from "@/components/ui/primitives";
import { Icon } from "@/components/nx/Icon";
import { DomainsSubHero } from "@/components/customer/domains/DomainsSubHero";
import { DomainRegisterWizard } from "@/components/customer/DomainRegisterWizard";
import type { DomainCheckResult } from "@/components/customer/DomainSearch";
import { findDomainInboxPlan } from "@/lib/domain-inbox-email";
import { geoapifyConfigured } from "@/lib/geoapify";

export const dynamic = "force-dynamic";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

export default async function RegisterDomainPage({
  searchParams,
}: {
  searchParams: Promise<{ domain?: string }>;
}) {
  const user = await requireUser();
  const { domain: raw } = await searchParams;
  const domain = (raw ?? "").toLowerCase().trim();
  const valid = DOMAIN_RE.test(domain);
  const configured = registrarConfigured();

  // The sandbox has no registrar credentials, so a real registration can't
  // complete there — but the checkout itself still has to be walkable and
  // reviewable, the same way search is. Show the wizard; the final step
  // reports honestly that registration needs a registrar connected.
  if (!configured && !SANDBOX) {
    return (
      <DomainsSubHero title="Register a domain" sub="Secure your name in a few quick steps.">
        <div className="rounded-[16px] border border-rim-hi bg-well px-6 py-14 text-center">
          <Icon name="globe2" size={30} className="mx-auto" />
          <h2 className="mt-4 text-[17px] font-extrabold text-white">Domain registration isn&apos;t available yet</h2>
          <p className="mx-auto mt-2 max-w-[46ch] text-[13px] leading-relaxed text-tx-dim">
            Registration activates once this feature is configured. Domains already on your account stay
            fully manageable in the meantime.
          </p>
          <Link href="/dashboard/domains" className="btn-secondary mt-5 inline-flex px-5">
            Back to domains
          </Link>
        </div>
      </DomainsSubHero>
    );
  }

  // Live availability + price for the pre-selected domain (best-effort). In the
  // sandbox this throws or comes back empty, and the wizard simply re-checks
  // client-side against the same endpoint the search uses.
  let initialCheck: DomainCheckResult | null = null;
  if (valid && configured) {
    try {
      const [check] = await checkDomains([domain]);
      if (check) {
        const dot = check.domain.indexOf(".");
        const available = check.available && check.priceCents !== null;
        initialCheck = {
          domain: check.domain,
          sld: dot > 0 ? check.domain.slice(0, dot) : check.domain,
          tld: dot > 0 ? check.domain.slice(dot + 1) : "",
          status: available ? "available" : "taken",
          available,
          premium: check.premium,
          priceCents: available ? check.priceCents : null,
          renewCents: available ? check.renewCents : null,
        };
      }
    } catch {
      /* registrar briefly unreachable — the wizard re-checks client-side */
    }
  }

  // Real figures for the bundled-mailbox note, read from the same HostingPlan
  // rows /web-hosting prices its cards from — never a guessed number.
  const hostingPlans = await db.hostingPlan.findMany({
    where: { active: true },
    select: { priceCents: true, mailboxes: true },
    orderBy: { priceCents: "asc" },
  });
  const hostingFromCents = hostingPlans.length ? hostingPlans[0].priceCents : null;
  const maxBundledMailboxes = hostingPlans.length ? Math.max(...hostingPlans.map((p) => p.mailboxes)) : null;

  const inboxPlan = await findDomainInboxPlan();

  return (
    <DomainsSubHero
      title="Register a domain"
      sub={valid ? `Securing ${domain} — a few quick steps and it's yours.` : "Secure your name in a few quick steps."}
    >
      {!configured && SANDBOX && (
        <p className="mb-5 rounded-[12px] border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-[12.5px] text-amber-300">
          Sandbox — no registrar is connected here, so you can walk the whole checkout but the final step
          can&apos;t complete a real registration.
        </p>
      )}

      <div className="grid gap-5 lg:grid-cols-[1fr_320px]">
        <div className="min-w-0">
          <DomainRegisterWizard
            initialDomain={valid ? domain : ""}
            initialCheck={initialCheck}
            defaultEmail={user.email}
            balanceCents={user.balanceCents}
            freeInboxPlan={inboxPlan ? { mailboxes: inboxPlan.mailboxes, storageGB: inboxPlan.storageGB } : null}
            geoapifyEnabled={geoapifyConfigured()}
          />
        </div>

        <aside className="space-y-4">
          <div className="rounded-[16px] border border-[#7b3fef]/45 bg-[linear-gradient(150deg,rgba(103,50,224,.55),rgba(37,63,190,.35)_60%,rgba(20,40,120,.3))] p-5">
            <span className="grid h-12 w-12 place-items-center rounded-[13px] border border-white/20 bg-white/10">
              <Icon name="gift" size={21} tone="inherit" className="text-fuchsia-300" />
            </span>
            <h3 className="mt-3.5 text-[17px] font-extrabold text-white">Included free</h3>
            <ul className="mt-4 space-y-2.5">
              {[
                inboxPlan ? `${inboxPlan.mailboxes} business mailbox, ${inboxPlan.storageGB} GB` : "A free business inbox",
                "WHOIS privacy protection",
                "Full DNS management",
              ].map((f) => (
                <li key={f} className="flex items-center gap-2.5 text-[13.5px] text-white/95">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#e879f9" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="flex-none">
                    <path d="M20 6 9 17l-5-5" />
