                {maxBundledMailboxes && maxBundledMailboxes > 1 ? `up to ${maxBundledMailboxes}` : "a"}{" "}
                mailbox{maxBundledMailboxes === 1 ? "" : "es"} free with every plan, from{" "}
                {fmtMoney(hostingFromCents)}/mo — first month free.
              </p>
              <Link href="/web-hosting" className="btn-secondary mt-3.5 w-full justify-center text-xs">
                See hosting plans
              </Link>
