"use client";

import { useEffect, useRef } from "react";
import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";

/* Domains' own light field — same canvas technique every other account
 * page's aurora uses (sine-path ribbon strokes, additive blend, a blurred
 * halo plus a hard-edged core), its own ribbon family: blue into violet into
 * magenta, echoing the concept art's globe glow — a network/global-reach
 * palette, distinct from SSL's green "verified" one or Team's own mix.
 */
type Ribbon = {
  y: number; amp: number; freq: number; speed: number; phase: number;
  width: number; hue: [number, number]; alpha: number;
};

const RIBBONS: Ribbon[] = [
  { y: 0.21, amp: 0.15, freq: 0.8,  speed: 0.12,  phase: 0.6, width: 58, hue: [206, 246], alpha: 0.19 },
  { y: 0.35, amp: 0.18, freq: 0.72, speed: -0.11, phase: 2.4, width: 68, hue: [246, 286], alpha: 0.16 },
  { y: 0.15, amp: 0.09, freq: 1.55, speed: 0.21,  phase: 4.0, width: 34, hue: [286, 318], alpha: 0.18 },
  { y: 0.29, amp: 0.06, freq: 2.3,  speed: 0.25,  phase: 5.6, width: 15, hue: [210, 232], alpha: 0.22 },
];

export function DomainsAurora() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d", { alpha: true });
    if (!ctx) return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, t = 0, running = true;

    const fit = () => {
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const r = cv.getBoundingClientRect();
      cv.width = Math.max(1, Math.round(r.width * dpr));
      cv.height = Math.max(1, Math.round(r.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const strand = (r: Ribbon, w: number, h: number, time: number, isLight: boolean) => {
      ctx.strokeStyle = auroraStrandGradient(ctx, r, w, isLight);
      ctx.lineWidth = r.width;
      ctx.lineCap = "round";
      ctx.beginPath();
      for (let x = 0; x <= w; x += 8) {
        const u = x / w;
        const y = h * (r.y
          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    const draw = () => {
      if (!running) return;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "blur(4px)";
      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
      ctx.globalCompositeOperation = "source-over";
      t += 0.014;
      raf = requestAnimationFrame(draw);
    };

    fit();
    if (reduced) {
      t = 2.4;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
    } else {
      raf = requestAnimationFrame(draw);
    }

    const onResize = () => fit();
    const onVis = () => {
      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
    };
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      running = false;
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div aria-hidden
         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[460px] overflow-hidden lg:left-[76px] xl:left-[248px]">
      {/* This canvas paints with globalCompositeOperation "lighter" in dark
          mode, but reads document.documentElement's data-theme once per
          frame and switches to normal "source-over" blending with darker,
          higher-alpha stops in light mode — see auroraTheme.ts. Additive
          blending alone only ever brightens, which is what washed this to a
          flat grey blob before; it is no longer hidden in light mode. */}
      <canvas ref={ref} className="h-full w-full opacity-80" />
      <span className="nx-aurora-dot" style={{ left: "15%", top: "17%", animationDelay: "0.5s" }} />
      <span className="nx-aurora-dot" style={{ left: "39%", top: "9%", animationDelay: "2.1s" }} />
      <span className="nx-aurora-dot" style={{ left: "61%", top: "23%", animationDelay: "3.3s" }} />
      <span className="nx-aurora-dot" style={{ left: "81%", top: "12%", animationDelay: "1.3s" }} />
      {/* Every stop mixes the theme's OWN background rather than a literal
          dark navy — see the identical fix on PlateBg's fade, same bug. */}
      <span className="absolute inset-0"
            style={{ background: "linear-gradient(180deg, color-mix(in srgb, var(--color-bg) 6%, transparent) 0%, color-mix(in srgb, var(--color-bg) 32%, transparent) 46%, color-mix(in srgb, var(--color-bg) 78%, transparent) 76%, var(--color-bg) 98%)" }} />
    </div>
  );
}
