"use client";

import { useState, type ReactNode } from "react";

const TABS = [
  { key: "search", label: "Search & Register" },
  { key: "mine", label: "My Domains" },
  { key: "transfers", label: "Transfers" },
  { key: "ideas", label: "Find a name" },
] as const;

type TabKey = (typeof TABS)[number]["key"];

/**
 * The domains page's tab bar. Every panel is a real section of THIS page —
 * transfers and the name generator used to navigate off to their own routes,
 * which meant leaving the page (and its hero) behind to do one step of the
 * same job. They are rendered here instead and simply swapped in place.
 *
 * Panels arrive already rendered from the server component, so switching tabs
 * costs nothing and no data is refetched.
 */
export function DomainsTabs({
  search, mine, transfers, ideas, sidebar,
}: {
  search: ReactNode;
  mine: ReactNode;
  transfers: ReactNode | null;
  ideas: ReactNode | null;
  /** Persistent rail, shown beside whichever panel is active. */
  sidebar: ReactNode;
}) {
  const [tab, setTab] = useState<TabKey>("search");
  const available: Record<TabKey, ReactNode | null> = { search, mine, transfers, ideas };
  const shown = TABS.filter((t) => available[t.key] !== null);

  return (
    <>
      <nav className="relative mt-7 flex flex-wrap items-center gap-7 border-b border-rim-soft">
        {shown.map((t) => (
          <button
            key={t.key}
            type="button"
            onClick={() => setTab(t.key)}
            className={"nx-tab " + (tab === t.key ? "nx-tab-on" : "")}
          >
            {t.label}
          </button>
        ))}
      </nav>

      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_336px]">
        <div className="min-w-0">{available[tab]}</div>
        <aside className="space-y-4">{sidebar}</aside>
      </div>
    </>
  );
}
