  type ResultFilter,
  type ResultSort,
} from "./DomainResultsModal";

type ApiResponse = {
  exact?: DomainCheckResult | null;
  results?: DomainCheckResult[];
  error?: string;
  /** Set by the sandbox: these are sample results, not a live lookup. */
  demo?: boolean;
};

/** Six quick-pick extensions with their indicative "from" prices, straight
 *  off the curated catalog (components/marketing/tlds.ts) — a live search
 *  always replaces these with the registrar's real quote for the typed name. */
const QUICK_PICKS = [".com", ".net", ".org", ".io", ".co", ".app"]
  .map((tld) => POPULAR_TLDS.find((t) => t.tld === tld))
  .filter((t): t is { tld: string; fromCents: number } => Boolean(t));

/**
 * The "Find your perfect domain" panel on the domains page, and the owner of
 * the whole search interaction: typing here and hitting Search opens the
 * full results modal, which keeps searching from its own field.
 */
export function DomainSearchPanel({ configured, sandbox = false }: { configured: boolean; sandbox?: boolean }) {
  // Searchable in the sandbox even with no registrar wired up — the endpoint
  // answers there with clearly-flagged sample data so the flow is reviewable.
  const searchable = configured || sandbox;
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exact, setExact] = useState<DomainCheckResult | null>(null);
  const [results, setResults] = useState<DomainCheckResult[]>([]);
  const [demo, setDemo] = useState(false);
  const [filter, setFilter] = useState<ResultFilter>("all");
  const [sort, setSort] = useState<ResultSort>("price-asc");
  const [cart, setCart] = useState<CartItem[]>([]);
  const reqId = useRef(0);

  const runSearch = useCallback(async (raw: string) => {
    const query = raw.trim().toLowerCase();
    if (query.length < 2) return;
    const id = ++reqId.current;
    setOpen(true);
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { cache: "no-store" });
      const json: ApiResponse = await res.json();
      if (id !== reqId.current) return; // a newer search already superseded this one
      setError(json.error ?? null);
      setExact(json.exact ?? null);
      setResults(Array.isArray(json.results) ? json.results : []);
      setDemo(Boolean(json.demo));
    } catch {
      if (id !== reqId.current) return;
      setError("Search failed — try again.");
      setExact(null);
      setResults([]);
    } finally {
      if (id === reqId.current) setLoading(false);
    }
  }, []);

