"use client";

import { useActionState, useState, useTransition } from "react";
import {
  renewDomainAction,
  toggleDomainAutoRenew,
  addDnsRecord,
  deleteDnsRecord,
  pointDomainAtServer,
} from "@/lib/actions-domains";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";

export function DomainAutoRenewToggle({
  domainId,
  autoRenew,
}: {
  domainId: string;
  autoRenew: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        type="button"
        role="switch"
        aria-checked={autoRenew}
        aria-label="Auto-renew this domain"
        disabled={pending}
        onClick={() =>
          // Previously the returned/thrown result was DISCARDED, so a failed
          // toggle (e.g. Forbidden) was a silent no-op — the switch snapped back
          // on the next render with no explanation. Capture and surface it inline.
          start(async () => {
            setError(null);
            try {
              const res = (await toggleDomainAutoRenew(domainId)) as { error?: string } | void;
              if (res?.error) setError(res.error);
            } catch {
              setError("Couldn’t update auto-renew — try again.");
            }
          })
        }
        title={autoRenew ? "Auto-renew is on — click to turn off" : "Auto-renew is off — click to turn on"}
        className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400 disabled:opacity-50 ${
          autoRenew ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
        }`}
      >
        <span
          className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
            autoRenew ? "left-[18px]" : "left-0.5"
          }`}
        />
      </button>
    </span>
  );
}

export function RenewDomainButton({
  domainId,
  priceCents,
  termYears,
}: {
  domainId: string;
  priceCents: number;
  termYears: number;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const term = domainTerm(termYears);
  const total = domainTermPriceCents(priceCents, term.years);
  return (
    <div>
      <button
        className="btn-primary w-full"
        disabled={pending}
        onClick={() => {
          if (!window.confirm(`Renew this domain for ${term.label} (${fmtMoney(total)})?`)) return;
          start(async () => {
            setError(null);
            const res = await renewDomainAction(domainId);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "Renewing…" : `Renew now (+${term.label}, ${fmtMoney(total)})`}
      </button>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

export function PointAtServerButton({ domainId, ip }: { domainId: string; ip: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  return (
    <div>
      <button
        className="btn-secondary"
        disabled={pending}
        onClick={() => {
          if (
            !window.confirm(
              `Point @ and www at ${ip}? Existing A records for @ and www will be replaced.`
            )
          )
            return;
          start(async () => {
            setError(null);
            setDone(false);
            const res = await pointDomainAtServer(domainId);
            if (res?.error) setError(res.error);
            else setDone(true);
          });
        }}
      >
        {pending ? "Updating DNS…" : "Point at my server"}
      </button>
      {done && (
        <p className="mt-2 text-sm text-emerald-400">
          DNS updated — propagation can take up to an hour.
        </p>
      )}
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

const DNS_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV"] as const;
const TTL_PRESETS = [
  [300, "5 min"],
  [1800, "30 min"],
  [3600, "1 hour"],
  [14400, "4 hours"],
  [86400, "1 day"],
] as const;

const placeholders: Record<string, string> = {
  A: "203.0.113.10",
  AAAA: "2001:db8::1",
  CNAME: "target.example.com",
  TXT: "v=spf1 include:_spf.example.com ~all",
  MX: "mail.example.com",
  NS: "ns1.example.com",
  SRV: "10 5 5060 sip.example.com",
};

const hints: Record<string, string> = {
  A: "Points a name at an IPv4 address.",
  AAAA: "Points a name at an IPv6 address.",
  CNAME: "Aliases this name to another hostname.",
  TXT: "Free-form text — SPF, DKIM, domain verification.",
  MX: "Mail server for the domain. Lower priority wins.",
  NS: "Delegates a subdomain to other nameservers.",
  SRV: "Service record: weight port target.",
};

export function DnsAddForm({ domainId }: { domainId: string }) {
  const [state, action, pending] = useActionState(addDnsRecord, {} as { error?: string });
  const [type, setType] = useState<string>("A");
  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
  // `<form action={fn}>` submit — including a REJECTED one. `addDnsRecord`
  // returns `{error}` for a malformed value or a name collision, so an
  // uncontrolled field blanked the entire Value the customer just pasted — a
  // long DKIM/SPF TXT string or a CNAME target — at the exact moment the red
  // error told them to fix it, leaving nothing to fix. Same reset class as
  // TicketForms.tsx and the port-forward form.
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const needsPriority = type === "MX" || type === "SRV";

  return (
    <form action={action} className="space-y-4">
      <input type="hidden" name="domainId" value={domainId} />
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Type</label>
          <select className="input" name="type" value={type} onChange={(e) => setType(e.target.value)}>
            {DNS_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Name</label>
          <input
            className="input"
            name="name"
            placeholder="@ or www"
            autoComplete="off"
            spellCheck={false}
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
        </div>
        <div className={needsPriority ? "" : "lg:col-span-2"}>
          <label className="label">Value</label>
          <input
            className="input font-mono text-xs"
            name="address"
            placeholder={placeholders[type] ?? "value"}
            required
            autoComplete="off"
            spellCheck={false}
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />
        </div>
        {needsPriority && (
          <div>
            <label className="label">Priority</label>
            <input className="input" name="mxPref" type="number" min={0} max={65535} defaultValue={10} />
          </div>
        )}
        <div>
          <label className="label">TTL</label>
          <select className="input" name="ttl" defaultValue={1800}>
            {TTL_PRESETS.map(([v, label]) => (
              <option key={v} value={v}>
                {label}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-xs text-slate-500">{hints[type]}</p>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add record"}
        </button>
      </div>
      {state?.error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {state.error}
        </div>
      )}
    </form>
  );
}

export function DnsDeleteButton({
  domainId,
  record,
}: {
  domainId: string;
  record: { name: string; type: string; address: string };
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger px-2.5 py-1 text-xs"
        disabled={pending}
        title="Delete record"
        onClick={() => {
          if (!window.confirm(`Delete ${record.type} record "${record.name}"?`)) return;
          start(async () => {
            setError(null);
            const res = await deleteDnsRecord(domainId, record);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "…" : "Delete"}
      </button>
    </span>
  );
}
import { Badge } from "@/components/ui/primitives";

export type ChecklistItem = { label: string; done: boolean; hint?: string };

/**
 * Small progress card summarising how "set up" a domain is. Pure presentational —
 * the parent page computes the items from the domain, its DNS records, and the
 * user's servers, so there is no client-side logic here.
 */
export function DomainChecklist({ items }: { items: ChecklistItem[] }) {
  const done = items.filter((i) => i.done).length;
  const pct = items.length ? Math.round((done / items.length) * 100) : 0;
  const complete = done === items.length;

  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="font-semibold">Setup checklist</h2>
        <Badge tone={complete ? "green" : done === 0 ? "slate" : "brand"}>
          {done}/{items.length} done
        </Badge>
      </div>

      <div className="mb-4 h-2 overflow-hidden rounded-full bg-white/[0.06]">
        <div
          className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all"
          style={{ width: `${pct}%` }}
        />
      </div>

      <ul className="space-y-2.5">
        {items.map((item) => (
          <li key={item.label} className="flex items-start gap-3">
            <span
              className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border text-[11px] ${
                item.done
                  ? "border-emerald-500/50 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 bg-white/[0.03] text-slate-500"
              }`}
            >
              {item.done ? "✓" : ""}
            </span>
            <div className="min-w-0">
              <p className={`text-sm ${item.done ? "text-slate-200" : "text-slate-400"}`}>{item.label}</p>
              {!item.done && item.hint && <p className="text-xs text-slate-500">{item.hint}</p>}
            </div>
          </li>
        ))}
      </ul>

      {complete && (
        <p className="mt-4 text-sm text-emerald-400">Nice — this domain is fully configured.</p>
      )}
    </div>
  );
}

