export type DomainRow = {
  id: string;
  name: string;
  status: string;
  expiresAtIso: string | null;
  autoRenew: boolean;
  /** "Nxeon DNS" when the domain is on our default nameservers, else "Custom". */
  nameserverLabel: string;
  emailEnabled: boolean;
  priceCents: number;
};

type StatusFilter = "all" | "active" | "expiring" | "pending";

function daysUntil(iso: string): number {
  return Math.ceil((new Date(iso).getTime() - Date.now()) / 86_400_000);
}

/** "Dec 12, 2026" — the concept's own format. Rendered from an ISO string
 *  with an explicit UTC timezone so the server and the browser agree. */
function fmtDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", {
    year: "numeric", month: "short", day: "numeric", timeZone: "UTC",
  });
}

const STATUS_LABEL: Record<string, { label: string; dot: string; text: string }> = {
  ACTIVE: { label: "Active", dot: "bg-emerald-400", text: "text-emerald-400" },
  PENDING: { label: "Pending", dot: "bg-amber-400", text: "text-amber-400" },
  TRANSFER_PENDING: { label: "Transferring", dot: "bg-amber-400", text: "text-amber-400" },
  TRANSFER_FAILED: { label: "Transfer failed", dot: "bg-red-400", text: "text-red-400" },
  EXPIRED: { label: "Expired", dot: "bg-red-400", text: "text-red-400" },
  FAILED: { label: "Failed", dot: "bg-red-400", text: "text-red-400" },
};

function Checkbox({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
      className={
        "grid h-[18px] w-[18px] flex-none place-items-center rounded-[5px] border transition " +
        (checked ? "border-brand-400 bg-brand-500/80" : "border-rim-hi bg-well hover:border-brand-400/60")
      }
    >
      {checked && (
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M20 6 9 17l-5-5" />
        </svg>
      )}
    </button>
  );
}

/** Per-row overflow menu. Only real actions — every item here either
 *  navigates somewhere that exists or calls a server action that exists. */
function RowMenu({ row }: { row: DomainRow }) {
  const [open, setOpen] = useState(false);
  return (
    <span className="relative">
      <button
        type="button"
        aria-label={`More actions for ${row.name}`}
        onClick={() => setOpen((v) => !v)}
        onBlur={() => setTimeout(() => setOpen(false), 120)}
        className="grid h-[30px] w-[30px] place-items-center rounded-[8px] text-tx-faint transition hover:bg-white/[0.06] hover:text-white"
      >
        <Icon name="ellipsis" size={15} tone="inherit" />
      </button>
      {open && (
        <span className="absolute right-0 top-[34px] z-20 flex w-[186px] flex-col overflow-hidden rounded-[11px] border border-rim-hi bg-surface py-1 shadow-2xl">
          <Link href={`/dashboard/domains/${row.id}`} className="px-3 py-2 text-left text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">
            Manage domain
          </Link>
          <Link href={`/dashboard/domains/${row.id}#your-dns`} className="px-3 py-2 text-left text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">
            DNS records
          </Link>
          <Link href="/dashboard/email" className="px-3 py-2 text-left text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">
            Email inbox
          </Link>
        </span>
      )}
    </span>
  );
}

