/**
 * Client-side DNS record checks for the domain DNS editor.
 *
 * These run as the customer types, so a bad value is caught and explained before
 * anything is submitted. They do NOT replace the server's checks
 * (`addDnsRecord` in lib/actions-domains.ts still validates and our DNS still
 * has the final say). They only catch the mistakes we can see locally and give a
 * plain-English fix for each one.
 *
 * Pure and dependency-free so it can be unit-tested and shipped to the browser.
 */

export const DNS_RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV"] as const;
export type DnsRecordType = (typeof DNS_RECORD_TYPES)[number];

export type DnsDraft = {
  type: string;
  /** "@", "" (both mean the apex), "www", "mail", "_dmarc", "*" … */
  name: string;
  value: string;
  priority?: number | string | null;
};

export type DnsCheck = {
  ok: boolean;
  /** Which field the problem is in, so the form can mark it. */
  field?: "name" | "value" | "priority";
  /** Why it is wrong and how to fix it. Only present when `ok` is false. */
  error?: string;
  /** The full hostname the record will answer for, e.g. "www.example.com". */
  fqdn: string;
};

const IPV4_RE = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
const LABEL_RE = /^(\*|_?[a-z0-9]([a-z0-9_-]{0,61}[a-z0-9])?)$/i;
const HOSTNAME_RE = /^(?=.{1,253}\.?$)([a-z0-9_]([a-z0-9_-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,62}\.?$/i;

export function isIPv4(v: string): boolean {
  return IPV4_RE.test(v.trim());
}

/** RFC 4291 text forms, including "::" compression and an embedded IPv4 tail. */
export function isIPv6(v: string): boolean {
  const s = v.trim();
  if (!s.includes(":") || /[^0-9a-f:.]/i.test(s)) return false;
  if ((s.match(/::/g) ?? []).length > 1) return false;
  let tail4 = 0;
  let head = s;
  const lastColon = s.lastIndexOf(":");
  const maybe4 = s.slice(lastColon + 1);
  if (maybe4.includes(".")) {
    if (!isIPv4(maybe4)) return false;
    tail4 = 2;
    head = s.slice(0, lastColon + 1) + "0"; // placeholder group, re-counted below
  }
  const compressed = head.includes("::");
  const groups = head.split(":").filter((g, i, a) => !(g === "" && (i === 0 || i === a.length - 1 || compressed)));
  const real = groups.filter((g) => g !== "");
  if (!real.every((g) => /^[0-9a-f]{1,4}$/i.test(g))) return false;
  const count = real.length - (tail4 ? 1 : 0) + tail4;
  return compressed ? count < 8 : count === 8;
}

export function isHostname(v: string): boolean {
  return HOSTNAME_RE.test(v.trim());
}

/** The apex is written "@" or left blank — both mean the bare domain. */
export function isApex(name: string): boolean {
  const n = name.trim();
  return n === "" || n === "@";
}

/**
 * Turn what the customer typed into the full name the record will answer for.
 * Customers often paste the full name ("www.example.com"); that is accepted and
 * treated as "www", the way most DNS editors handle it.
 */
export function normaliseName(name: string, domain: string): string {
  const n = name.trim().toLowerCase().replace(/\.$/, "");
  const d = domain.toLowerCase();
  if (n === "" || n === "@" || n === d) return "@";
  if (n.endsWith("." + d)) return n.slice(0, -(d.length + 1));
  return n;
}

export function fqdnFor(name: string, domain: string): string {
  const n = normaliseName(name, domain);
  return n === "@" ? domain.toLowerCase() : `${n}.${domain.toLowerCase()}`;
}

