      return bad("name", "Use letters, numbers and hyphens only, like www, mail or shop. Use @ for the bare domain.", fqdn);
    }
    if (labels.slice(1).includes("*")) {
      return bad("name", "A wildcard (*) can only be the first part of the name, like *.shop.", fqdn);
    }
  }

