  if (value.length > 500) return bad("value", "That value is too long. DNS records hold up to 500 characters here.", fqdn);

  switch (type) {
    case "A":
      if (!isIPv4(value)) {
        return bad("value", isIPv6(value)
          ? "That's an IPv6 address. Change the type to AAAA, or enter an IPv4 address like 203.0.113.10."
          : "An A record needs an IPv4 address, like 203.0.113.10.", fqdn);
      }
      break;
    case "AAAA":
      if (!isIPv6(value)) {
        return bad("value", isIPv4(value)
          ? "That's an IPv4 address. Change the type to A, or enter an IPv6 address like 2001:db8::1."
          : "An AAAA record needs an IPv6 address, like 2001:db8::1.", fqdn);
