      if (isIPv4(value) || isIPv6(value)) {
        return bad("value", "A CNAME points to a hostname, not an IP address. Use an A record to point at an IP.", fqdn);
      }
      if (!isHostname(value)) return bad("value", "A CNAME needs a hostname, like target.example.com.", fqdn);
      if (value.replace(/\.$/, "").toLowerCase() === fqdn) {
        return bad("value", "A CNAME can't point to itself.", fqdn);
      }
      break;
    case "MX":
    case "NS":
      if (isIPv4(value) || isIPv6(value)) {
        return bad("value", `An ${type} record points to a hostname, not an IP address. Enter a name like ${type === "MX" ? "mail.example.com" : "ns1.example.com"}.`, fqdn);
