/** One-line description of what a record does, for the records table. */
export function describeRecord(type: string, name: string, value: string, domain: string): string {
  const host = fqdnFor(name, domain);
  const v = value.replace(/\.$/, "");
  switch (type.toUpperCase()) {
    case "A":
    case "AAAA":
    case "ALIAS":
      return `${host} → ${v}`;
    case "CNAME":
      return `${host} is an alias of ${v}`;
    case "MX":
      return `Mail for ${host} goes to ${v}`;
    case "NS":
      return `${host} is delegated to ${v}`;
    case "SRV":
      return `Service ${host}`;
