/**
 * Which of the customer's own Nxeon services a domain is attached to — the
 * "linked to" column on the domains list.
 *
 * Built only from rows we actually hold (a hosting account's primary or addon
 * domain, a website on a VPS, a server's custom domain). It never guesses from
 * DNS, so a domain only shows a link when one really exists on the account.
 *
 * Pure: the loader in lib/domain-links.ts fetches the rows, this decides.
 */

export type LinkSource = {
  kind: "hosting" | "website" | "server";
  /** The domain or hostname as stored on that row. */
  domain: string;
  /** What to call the service in the UI, e.g. a server label. */
  label: string;
  href: string;
};

export type DomainLink = {
  kind: LinkSource["kind"];
  label: string;
  href: string;
  /** How many services in total use this domain, when more than one. */
  more: number;
};

const clean = (d: string) => d.trim().toLowerCase().replace(/\.$/, "");

/**
 * A source matches a domain when it IS the domain or a subdomain of it
 * ("shop.example.com" belongs to "example.com"), never a lookalike
 * ("myexample.com" does not).
 */
export function belongsTo(sourceDomain: string, domain: string): boolean {
  const s = clean(sourceDomain);
  const d = clean(domain);
  if (!s || !d) return false;
  return s === d || s.endsWith("." + d);
}

const RANK: Record<LinkSource["kind"], number> = { hosting: 0, website: 1, server: 2 };

export function linkFor(domain: string, sources: LinkSource[]): DomainLink | null {
  const hits = sources
    .filter((s) => belongsTo(s.domain, domain))
    // Exact matches beat subdomains, then hosting > website > server.
    .sort((a, b) => {
      const ea = clean(a.domain) === clean(domain) ? 0 : 1;
      const eb = clean(b.domain) === clean(domain) ? 0 : 1;
      return ea - eb || RANK[a.kind] - RANK[b.kind];
    });
  // The same service can appear twice (a site and its www alias); count it once.
  const unique = hits.filter((h, i) => hits.findIndex((x) => x.href === h.href) === i);
  if (unique.length === 0) return null;
  const first = unique[0];
  return { kind: first.kind, label: first.label, href: first.href, more: unique.length - 1 };
}

export function linksByDomain(domains: string[], sources: LinkSource[]): Map<string, DomainLink | null> {
  return new Map(domains.map((d) => [d, linkFor(d, sources)]));
}

