import { db } from "@/lib/db";
import { linksByDomain, type DomainLink, type LinkSource } from "@/lib/nx/domain-links";

/**
 * Loads the customer's own services that carry a domain name and works out
 * which domain each belongs to. Read-only, three small queries scoped to the
 * user, no registrar or DNS lookups — safe to run on every list render.
