import { test } from "node:test";
import assert from "node:assert/strict";

import {
  validateDnsRecord,
  isIPv4,
  isIPv6,
  isHostname,
  normaliseName,
  fqdnFor,
  describeRecord,
} from "../lib/nx/dns-validate.ts";
import { belongsTo, linkFor, linksByDomain, type LinkSource } from "../lib/nx/domain-links.ts";
import { sandboxDnsList, sandboxDnsAdd, sandboxDnsDelete, sandboxDnsReset } from "../lib/registrar-sandbox-dns.ts";
import { expiryState, renewalQuote } from "../lib/nx/domain-lifecycle.ts";

const D = "example.com";

test("ipv4", () => {
  for (const ok of ["203.0.113.10", "0.0.0.0", "255.255.255.255", "10.0.0.1"]) assert.ok(isIPv4(ok), ok);
  for (const no of ["256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "a.b.c.d", ""]) assert.ok(!isIPv4(no), no);
});

test("ipv6", () => {
  for (const ok of ["2001:db8::1", "::1", "::", "fe80::1:2:3:4", "2001:0db8:0000:0000:0000:ff00:0042:8329", "::ffff:192.0.2.1"]) {
    assert.ok(isIPv6(ok), ok);
  }
  for (const no of ["2001:db8:::1", "1::2::3", "2001:db8", "12345::1", "gggg::1", "203.0.113.10", "1:2:3:4:5:6:7:8:9"]) {
    assert.ok(!isIPv6(no), no);
  }
});

test("hostname", () => {
  for (const ok of ["mail.example.com", "aspmx.l.google.com.", "a.io", "_spf.google.com"]) assert.ok(isHostname(ok), ok);
  for (const no of ["localhost", "-bad.com", "bad-.com", "has space.com", "example.", ""]) assert.ok(!isHostname(no), no);
});

test("name normalisation and fqdn", () => {
  assert.equal(normaliseName("@", D), "@");
  assert.equal(normaliseName("", D), "@");
  assert.equal(normaliseName("example.com", D), "@");
  assert.equal(normaliseName("WWW.example.com.", D), "www");
  assert.equal(normaliseName("shop", D), "shop");
  assert.equal(fqdnFor("@", D), "example.com");
  assert.equal(fqdnFor("www", D), "www.example.com");
});

test("A / AAAA records", () => {
  assert.ok(validateDnsRecord({ type: "A", name: "@", value: "203.0.113.10" }, D).ok);
  const v6InA = validateDnsRecord({ type: "A", name: "@", value: "2001:db8::1" }, D);
  assert.equal(v6InA.ok, false);
  assert.equal(v6InA.field, "value");
  assert.match(v6InA.error!, /AAAA/);
  assert.ok(validateDnsRecord({ type: "AAAA", name: "www", value: "2001:db8::1" }, D).ok);
  assert.match(validateDnsRecord({ type: "AAAA", name: "www", value: "203.0.113.10" }, D).error!, /Change the type to A/);
});

test("CNAME rules", () => {
  assert.ok(validateDnsRecord({ type: "CNAME", name: "www", value: "example.com." }, D).ok);
  const apex = validateDnsRecord({ type: "CNAME", name: "@", value: "target.example.net" }, D);
  assert.equal(apex.ok, false);
  assert.equal(apex.field, "name");
  assert.match(validateDnsRecord({ type: "CNAME", name: "www", value: "203.0.113.10" }, D).error!, /not an IP/);
  assert.match(validateDnsRecord({ type: "CNAME", name: "www", value: "www.example.com" }, D).error!, /itself/);
});

test("MX needs a hostname and a priority", () => {
  assert.ok(validateDnsRecord({ type: "MX", name: "@", value: "aspmx.l.google.com.", priority: 1 }, D).ok);
  assert.equal(validateDnsRecord({ type: "MX", name: "@", value: "203.0.113.10", priority: 10 }, D).field, "value");
  assert.equal(validateDnsRecord({ type: "MX", name: "@", value: "mail.example.com", priority: "" }, D).field, "priority");
  assert.equal(validateDnsRecord({ type: "MX", name: "@", value: "mail.example.com", priority: 70000 }, D).field, "priority");
});

test("NS at apex is redirected to the nameservers tab", () => {
  assert.match(validateDnsRecord({ type: "NS", name: "@", value: "ns1.other.net" }, D).error!, /Nameservers tab/);
  assert.ok(validateDnsRecord({ type: "NS", name: "dev", value: "ns1.other.net" }, D).ok);
});

test("SRV shape", () => {
  assert.ok(validateDnsRecord({ type: "SRV", name: "_sip._tcp", value: "5 5060 sip.example.com", priority: 10 }, D).ok);
  assert.equal(validateDnsRecord({ type: "SRV", name: "_sip._tcp", value: "5060 sip.example.com", priority: 10 }, D).field, "value");
  assert.equal(validateDnsRecord({ type: "SRV", name: "sip", value: "5 5060 sip.example.com", priority: 10 }, D).field, "name");
  assert.match(validateDnsRecord({ type: "SRV", name: "_sip._tcp", value: "5 0 sip.example.com", priority: 1 }, D).error!, /port/);
});

test("names: labels, wildcards, empty values", () => {
  assert.ok(validateDnsRecord({ type: "TXT", name: "_dmarc", value: "v=DMARC1; p=none" }, D).ok);
  assert.ok(validateDnsRecord({ type: "A", name: "*", value: "203.0.113.10" }, D).ok);
  assert.equal(validateDnsRecord({ type: "A", name: "shop.*", value: "203.0.113.10" }, D).field, "name");
  assert.equal(validateDnsRecord({ type: "A", name: "bad name", value: "203.0.113.10" }, D).field, "name");
  assert.equal(validateDnsRecord({ type: "TXT", name: "@", value: "   " }, D).field, "value");
  assert.equal(validateDnsRecord({ type: "TXT", name: "@", value: "x".repeat(501) }, D).field, "value");
});

test("describeRecord", () => {
  assert.equal(describeRecord("A", "www", "203.0.113.10", D), "www.example.com → 203.0.113.10");
  assert.match(describeRecord("TXT", "@", "v=spf1 include:_spf.google.com ~all", D), /^SPF/);
  assert.match(describeRecord("TXT", "_dmarc", "v=DMARC1; p=none", D), /^DMARC/);
  assert.match(describeRecord("MX", "@", "mail.example.com.", D), /Mail for example.com goes to mail.example.com$/);
});

const SRC: LinkSource[] = [
  { kind: "server", domain: "example.com", label: "web-prod", href: "/dashboard/servers/s1" },
  { kind: "hosting", domain: "example.com", label: "Web hosting", href: "/dashboard/hosting/h1" },
  { kind: "website", domain: "shop.example.com", label: "web-prod", href: "/dashboard/servers/s1" },
  { kind: "website", domain: "myexample.com", label: "other", href: "/dashboard/servers/s2" },
];

test("belongsTo never matches lookalikes", () => {
  assert.ok(belongsTo("example.com", "example.com"));
  assert.ok(belongsTo("Shop.Example.com.", "example.com"));
  assert.ok(!belongsTo("myexample.com", "example.com"));
  assert.ok(!belongsTo("", "example.com"));
});

test("linkFor ranks exact + hosting first and counts unique services", () => {
  const l = linkFor("example.com", SRC)!;
  assert.equal(l.kind, "hosting");
  assert.equal(l.href, "/dashboard/hosting/h1");
  assert.equal(l.more, 1); // server s1 (twice: custom domain + website) counts once
  assert.equal(linkFor("nothing.com", SRC), null);
  assert.equal(linkFor("myexample.com", SRC)!.href, "/dashboard/servers/s2");
  const m = linksByDomain(["example.com", "none.org"], SRC);
  assert.equal(m.get("none.org"), null);
});

test("sandbox DNS store: seeded, add, delete, isolated per domain", () => {
  sandboxDnsReset();
  const seeded = sandboxDnsList("one.example");
  assert.ok(seeded.length >= 3);
  assert.ok(seeded.some((r) => r.type === "A" && r.host === ""));
  sandboxDnsAdd("one.example", { host: "shop", type: "A", answer: "203.0.113.50", ttl: 300 });
  const after = sandboxDnsList("one.example");
  const added = after.find((r) => r.host === "shop")!;
  assert.ok(added);
  assert.equal(sandboxDnsList("two.example").some((r) => r.host === "shop"), false);
  sandboxDnsDelete("one.example", added.id);
  assert.equal(sandboxDnsList("one.example").some((r) => r.host === "shop"), false);
});

test("expiryState buckets", () => {
  const now = Date.parse("2026-10-06T12:00:00Z");
  const day = 86_400_000;
  assert.equal(expiryState(null, now).tone, "none");
  assert.equal(expiryState(new Date(now + 200 * day), now).tone, "ok");
  assert.equal(expiryState(new Date(now + 20 * day), now).tone, "soon");
  assert.equal(expiryState(new Date(now + 5 * day), now).tone, "urgent");
  const past = expiryState(new Date(now - 3 * day), now);
  assert.equal(past.tone, "expired");
  assert.equal(past.days, -3);
  // fraction of a 1-year term remaining, clamped 0..1
  assert.ok(expiryState(new Date(now + 400 * day), now).fraction <= 1);
  assert.equal(past.fraction, 0);
});

test("renewalQuote uses the frozen renewal price and term", () => {
  assert.deepEqual(renewalQuote({ priceCents: 999, renewPriceCents: 1599, termYears: 1 }), { perYearCents: 1599, years: 1, totalCents: 1599, higherThanFirstYear: true });
  assert.deepEqual(renewalQuote({ priceCents: 1299, renewPriceCents: null, termYears: 2 }), { perYearCents: 1299, years: 2, totalCents: 2598, higherThanFirstYear: false });
});

