import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";

/**
 * How close a domain is to its expiry, in the buckets the domains UI colours by.
 * Pure: `now` is passed in so server and tests agree.
 *
 *   ok      more than 30 days left
 *   soon    8–30 days
 *   urgent  0–7 days (including "expires today")
 *   expired past the expiry date
 *   none    no expiry known yet (pending, transferring, failed)
 */
export type ExpiryTone = "ok" | "soon" | "urgent" | "expired" | "none";

export type ExpiryState = {
  tone: ExpiryTone;
  /** Whole days until expiry; negative once expired; null when unknown. */
  days: number | null;
  /** Share of a one-year term still remaining (0..1), for the countdown bar. */
  fraction: number;
  /** "in 12 days", "expires today", "expired 3 days ago", "—". */
  text: string;
};

const DAY = 86_400_000;

export function expiryState(expiresAt: Date | string | null, now: number = Date.now()): ExpiryState {
  if (!expiresAt) return { tone: "none", days: null, fraction: 0, text: "—" };
  const t = typeof expiresAt === "string" ? Date.parse(expiresAt) : expiresAt.getTime();
  const days = Math.ceil((t - now) / DAY);
  const fraction = Math.max(0, Math.min(1, days / 365));
  if (days < 0) return { tone: "expired", days, fraction: 0, text: `expired ${-days} day${days === -1 ? "" : "s"} ago` };
  if (days === 0) return { tone: "urgent", days, fraction, text: "expires today" };
  const text = `in ${days} day${days === 1 ? "" : "s"}`;
  if (days <= 7) return { tone: "urgent", days, fraction, text };
  if (days <= 30) return { tone: "soon", days, fraction, text };
  return { tone: "ok", days, fraction, text };
}

/**
 * The renewal a customer will actually be charged: the renewal price frozen at
 * registration (falls back to the first-year price on older rows, the same rule
 * renewDomainAction and the auto-renew sweep use) over the domain's own term,
 * with the term discount from lib/billing-terms.
 */
export function renewalQuote(d: { priceCents: number; renewPriceCents?: number | null; termYears: number }) {
  const perYearCents = d.renewPriceCents ?? d.priceCents;
  const years = domainTerm(d.termYears).years;
  return {
    perYearCents,
    years,
    totalCents: domainTermPriceCents(perYearCents, years),
    higherThanFirstYear: perYearCents > d.priceCents,
  };
}

