/**
 * SANDBOX-ONLY in-memory DNS zone store.
 *
 * Used by lib/registrar.ts's record functions ONLY when NXEON_SANDBOX=1 AND no
 * registrar credentials are configured (a local agent box or the node-2
 * sandbox). Staging has real credentials, so it keeps using the real API; prod
 * has no NXEON_SANDBOX, so this file is never reached there.
 *
 * It exists so the DNS editor (records table, templates, add/delete) can be
 * walked and reviewed end to end without contacting a registrar. State lives in
 * process memory, is seeded deterministically per domain, and resets on restart.
 * Addresses come from the RFC 5737 documentation ranges.
 */

export type SandboxRecord = { id: number; host: string; type: string; answer: string; ttl: number; priority?: number };

type Store = { zones: Map<string, SandboxRecord[]>; nextId: number };
const g = globalThis as unknown as { __nxSandboxDns?: Store };
const store = (): Store => (g.__nxSandboxDns ??= { zones: new Map(), nextId: 1 });

function seed(domain: string): SandboxRecord[] {
  const s = store();
  const mk = (r: Omit<SandboxRecord, "id">): SandboxRecord => ({ id: s.nextId++, ...r });
  return [
    mk({ host: "", type: "A", answer: "198.51.100.20", ttl: 300 }),
    mk({ host: "www", type: "CNAME", answer: `${domain}.`, ttl: 300 }),
    mk({ host: "", type: "MX", answer: "mail.nxeon.cloud.", ttl: 3600, priority: 10 }),
    mk({ host: "", type: "TXT", answer: "v=spf1 a mx ~all", ttl: 3600 }),
    mk({ host: "_dmarc", type: "TXT", answer: "v=DMARC1; p=none", ttl: 3600 }),
  ];
}

function zone(domain: string): SandboxRecord[] {
  const key = domain.toLowerCase();
  const s = store();
  let z = s.zones.get(key);
  if (!z) {
    z = seed(key);
    s.zones.set(key, z);
  }
  return z;
}

export function sandboxDnsList(domain: string): SandboxRecord[] {
  return zone(domain).map((r) => ({ ...r }));
}

export function sandboxDnsAdd(domain: string, rec: Omit<SandboxRecord, "id">): void {
  const z = zone(domain);
  z.push({ id: store().nextId++, ...rec, ttl: rec.ttl ?? 300 });
}

export function sandboxDnsDelete(domain: string, id: number): void {
  const z = zone(domain);
  const i = z.findIndex((r) => r.id === id);
  if (i >= 0) z.splice(i, 1);
}

/** Tests only. */
export function sandboxDnsReset(): void {
  g.__nxSandboxDns = { zones: new Map(), nextId: 1 };
}

