"use client";

import { useId } from "react";

/**
 * Vector illustrations for the Domains area — drop-in replacements for the old
 * raster hero (`/nx/hero-domains-globe.webp`, a 900x600 bitmap that was blurry
 * at 2x, carried a baked-in glow halo, and stayed a dark picture in light mode).
 *
 * Everything here is inline SVG drawn from theme tokens (`--color-*`), so it is
 * sharp at any pixel density and re-colours itself for light mode. Animation is
 * CSS only, lives inside `prefers-reduced-motion: no-preference`, and is purely
 * decorative (aria-hidden).
 *
 * Shared on purpose: `BrandRamp` and `ArtStyles` are generic, so the Support and
 * SSL overhauls can reuse them (or merge them into a common file later) without
 * touching the domain-specific art below.
 */

/** The brand ramp, blue -> violet -> magenta, as an SVG gradient. */
export function BrandRamp({ id, x1 = "0", y1 = "0", x2 = "1", y2 = "1", opacity = 1 }: {
  id: string; x1?: string; y1?: string; x2?: string; y2?: string; opacity?: number;
}) {
  return (
    <linearGradient id={id} x1={x1} y1={y1} x2={x2} y2={y2}>
      <stop offset="0" style={{ stopColor: "var(--color-blue)", stopOpacity: opacity }} />
      <stop offset="0.55" style={{ stopColor: "var(--color-violet)", stopOpacity: opacity }} />
      <stop offset="1" style={{ stopColor: "var(--color-brand-c)", stopOpacity: opacity }} />
    </linearGradient>
  );
}

/* One stylesheet for every illustration in this file. Keyframes sit inside an
   at-rule (never inside a style rule — see CLAUDE.md, they are dropped there). */
const CSS = `
.nxa-chip{transform-box:fill-box;transform-origin:center}
.nxa-pk{opacity:0}
@media (prefers-reduced-motion:no-preference){
  @keyframes nxa-float{0%{transform:translateY(0)}100%{transform:translateY(-4px)}}
  @keyframes nxa-travel{0%{offset-distance:0%;opacity:0}12%{opacity:1}88%{opacity:1}100%{offset-distance:100%;opacity:0}}
  @keyframes nxa-spin{to{transform:rotate(360deg)}}
  @keyframes nxa-caret{0%,45%{opacity:1}50%,95%{opacity:0}100%{opacity:1}}
  @keyframes nxa-dash{to{stroke-dashoffset:-48}}
  @keyframes nxa-breathe{0%,100%{opacity:.55}50%{opacity:1}}
  .nxa-chip{animation:nxa-float 4.8s ease-in-out infinite alternate}
  .nxa-pk{animation:nxa-travel 3.6s cubic-bezier(.45,0,.55,1) infinite}
  .nxa-spin{transform-box:fill-box;transform-origin:center;animation:nxa-spin 26s linear infinite}
  .nxa-spin-fast{transform-box:fill-box;transform-origin:center;animation:nxa-spin 1.4s linear infinite}
  .nxa-caret{animation:nxa-caret 1.1s steps(1) infinite}
  .nxa-dash{animation:nxa-dash 1.6s linear infinite}
  .nxa-breathe{animation:nxa-breathe 3.2s ease-in-out infinite}
}
`;
export function ArtStyles() {
  return <style>{CSS}</style>;
}

/* ── the globe ───────────────────────────────────────────────────────────── */

type Pt = { x: number; y: number };

const CX = 300, CY = 150, R = 100;

/** A point on the globe's visible face from latitude/longitude (degrees). */
function onGlobe(lat: number, lon: number): Pt {
  const la = (lat * Math.PI) / 180, lo = (lon * Math.PI) / 180;
  return { x: CX + R * Math.cos(la) * Math.sin(lo), y: CY - R * Math.sin(la) };
}

/* Network nodes on the visible hemisphere and the links between them. */
const NODES: Pt[] = [
  onGlobe(38, -52), onGlobe(52, 8), onGlobe(14, 46), onGlobe(-22, -34), onGlobe(-8, 18), onGlobe(-44, 40), onGlobe(24, -10),
];
const LINKS: [number, number][] = [[0, 6], [6, 1], [6, 4], [4, 2], [3, 4], [4, 5], [1, 2]];

function arc(a: Pt, b: Pt, lift = 0.22): string {
  // Bow each link away from the globe's centre so it reads as a route over the
  // surface rather than a chord through it.
  const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
