      <g clipPath={`url(#${globeClip})`} fill="none" stroke={`url(#${gs})`} strokeWidth={1}>
        {lats.map((la) => {
          const y = CY - R * Math.sin((la * Math.PI) / 180);
          const w = R * Math.cos((la * Math.PI) / 180);
          return <ellipse key={`la${la}`} cx={CX} cy={y} rx={w} ry={w * 0.16} />;
        })}
        {lons.map((lo) => (
          <ellipse key={`lo${lo}`} cx={CX} cy={CY} rx={Math.abs(R * Math.sin((lo * Math.PI) / 180)) || 0.6} ry={R} />
        ))}
      </g>
      <circle cx={CX} cy={CY} r={R} fill="none" stroke={`url(#${g})`} strokeWidth={2} />

      {/* routes + travelling packets */}
      <g fill="none" strokeLinecap="round">
        {LINKS.map(([a, b], i) => {
          const d = arc(NODES[a], NODES[b]);
          return (
            <g key={i}>
              <path d={d} stroke={`url(#${g})`} strokeWidth={1.4} opacity={0.85} />
              <circle r={2.6} className="nxa-pk" style={{ fill: "var(--color-cyan)", offsetPath: `path('${d}')`, animationDelay: `${i * 0.7}s` } as React.CSSProperties} />
            </g>
          );
        })}
      </g>
      {NODES.map((n, i) => (
        <g key={i}>
          <circle cx={n.x} cy={n.y} r={6} style={{ fill: "var(--color-violet)" }} opacity={0.18} />
          <circle cx={n.x} cy={n.y} r={2.8} style={{ fill: i === 4 ? "var(--color-cyan)" : "var(--color-tx)" }} />
        </g>
      ))}

      {/* orbit, near side */}
      <g transform={`translate(${ORBIT.cx} ${ORBIT.cy}) rotate(${ORBIT.tilt})`}>
        <ellipse cx={0} cy={0} rx={ORBIT.rx} ry={ORBIT.ry} fill="none" stroke={`url(#${g})`} strokeWidth={1.6} clipPath={`url(#${clipFront})`} />
      </g>
      {chips.filter((c) => c.p.front).map((c) => <Chip key={c.label} {...c} grad={g} />)}
    </svg>
  );
}

/**
