52:    (ev: { type: "start" | "step" | "complete" | "dismiss"; step?: number }) => {
68:      // starting now stacked the tour card on top of it. Wait until it is dismissed.
124:          onDismiss={(i) => { send({ type: "dismiss", step: mode.kind === "auto" ? i : undefined }); close(); }}

  tour: TourDef;
  autoStart: boolean;
  resumeAt?: number;
  /** A brand-new run, as opposed to resuming an interrupted one. */
  fresh?: boolean;
  /** Write progress (owner, not impersonating). */
  persist: boolean;
  showButton?: boolean;
  className?: string;
}) {
  const [mode, setMode] = useState<Mode | null>(null);
  const started = useRef(false);

  /* Auto runs include the one-time "it's ready" step; replays skip it. Both
     index into their own list, and only auto runs persist `lastStep`, so a
     resume index always refers to the auto list. */
  const steps = useMemo(
    () => (mode?.kind === "replay" ? tour.steps.filter((s) => !s.autoOnly) : tour.steps),
    [mode?.kind, tour.steps],
  );

  const send = useCallback(
    (ev: { type: "start" | "step" | "complete" | "dismiss"; step?: number }) => {
      if (!persist) return;
      void recordTourEvent(tour.key, ev).catch(() => { /* a lost write only means the tour may show again */ });
    },
    [persist, tour.key],
  );

  /* Auto-start once, after the panel has hydrated and laid out. */
  useEffect(() => {
    if (!autoStart || started.current) return;
    let t: ReturnType<typeof setTimeout>;
    const attempt = () => {
      // Set inside the timer, not before it: React's dev double-invoke clears
      // the first timer, and a flag set eagerly would then block the second.
      if (started.current) return;
      // Another blocking modal (the one-time "How did you hear about us?" survey) is up:
      // starting now stacked the tour card on top of it. Wait until it is dismissed.
      if (document.querySelector("[data-blocking-prompt]")) {
        t = setTimeout(attempt, 600);
        return;
      }
      started.current = true;
      const startAt = fresh ? 0 : Math.min(resumeAt, tour.steps.length - 1);
      setMode({ kind: "auto", startAt });
      send({ type: "start" });
    };
    t = setTimeout(attempt, 700);
    return () => clearTimeout(t);
  }, [autoStart, fresh, resumeAt, tour.steps.length, send]);

