import Link from "next/link";
import { DomainOrbitArt } from "@/components/nx/visual/DomainArt";

/**
 * The header every Domains screen opens with: the portal's tracked eyebrow,
 * the H1, one line of explanation, and the vector orbit illustration on the
 * right. Replaces the old raster globe (`/nx/hero-domains-globe.webp`).
 *
 * `compact` is the shorter variant for task pages (register, transfer, ideas);
 * `back` adds the "All domains" link those pages need.
 */
export function DomainsHero({
  title,
  sub,
  compact = false,
  back = false,
  actions,
}: {
  title: React.ReactNode;
  sub?: React.ReactNode;
  compact?: boolean;
  back?: boolean;
  /** Primary buttons under the sub line. */
  actions?: React.ReactNode;
}) {
  return (
    <header className={"relative " + (compact ? "min-h-[132px] lg:min-h-[176px]" : "min-h-[150px] lg:min-h-[232px]")}>
      <DomainOrbitArt
        className={
          "pointer-events-none absolute right-[-12px] top-[-14px] hidden w-auto lg:block " +
          (compact ? "h-[190px]" : "h-[250px] xl:h-[262px]")
        }
      />
      <div className="relative max-w-[600px] pt-3 lg:pt-6">
        {back && (
          <Link
            href="/dashboard/domains"
            className="mb-3 inline-flex items-center gap-1.5 rounded-[9px] text-[12.5px] font-semibold text-tx-dim transition hover:text-tx focus-visible:outline-2 focus-visible:outline-offset-2"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M15 18l-6-6 6-6" />
            </svg>
            All domains
          </Link>
        )}
        <span className="block text-[11px] font-extrabold uppercase tracking-[0.24em] text-[#f21cff]">Network</span>
        <h1
          className={
            "mt-2 font-extrabold tracking-[-0.035em] text-white " +
            (compact ? "text-[28px] leading-[1.08] sm:text-[34px]" : "text-[34px] leading-[1.04] sm:text-[42px]")
          }
        >
          {title}
        </h1>
        {sub && <p className="mt-2 max-w-[56ch] text-[14px] leading-relaxed text-tx-dim">{sub}</p>}
        {actions && <div className="mt-4 flex flex-wrap items-center gap-2.5">{actions}</div>}
      </div>
    </header>
  );
}

