/**
 * Curated groupings for the domain-search result filters ("Popular",
 * "Business", "Country", "New"). These are editorial buckets over the same
 * curated catalog components/marketing/tlds.ts already owns — a judgement
 * about what an extension is FOR, which no registrar API returns.
 *
 * "On sale" is deliberately NOT here: that one is derived per-result from the
 * registrar's own numbers (first-year price below the renewal price), so it
 * reflects a real discount on the real quote rather than an editorial tag.
 */
export type TldGroup = "popular" | "business" | "country" | "new";

const POPULAR = new Set([".com", ".net", ".org", ".co", ".io", ".ai"]);
const BUSINESS = new Set([".com", ".co", ".biz", ".info", ".net", ".me"]);
const COUNTRY = new Set([".in", ".co.uk", ".ca", ".com.au", ".de", ".us", ".eu", ".me", ".tv"]);
const NEW = new Set([".app", ".dev", ".ai", ".xyz", ".shop", ".store", ".online", ".site", ".tech"]);

/** `tld` may arrive with or without its leading dot (the API returns "com"). */
export function tldGroupsFor(tld: string): TldGroup[] {
  const t = tld.startsWith(".") ? tld : `.${tld}`;
  const out: TldGroup[] = [];
  if (POPULAR.has(t)) out.push("popular");
  if (BUSINESS.has(t)) out.push("business");
  if (COUNTRY.has(t)) out.push("country");
  if (NEW.has(t)) out.push("new");
  return out;
}
