/* ── domains: the concept's gradient CTA ──────────────────────────────
   Blue → violet → magenta, the full brand sweep. Distinct from
   .btn-primary (which is the calmer, rim-swept button the rest of the
   product uses) — this is the "buy" button: search, register, checkout. */
.nx-cta {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  border-radius: 10px; font-weight: 700; color: #fff; white-space: nowrap;
  background: linear-gradient(100deg, #2f6fe0, #7b3fef 55%, #c33bea);
  box-shadow: 0 10px 26px -12px rgba(123, 63, 239, .85);
  transition: filter .16s ease, transform .16s ease;
}
.nx-cta:hover { filter: brightness(1.08); }
.nx-cta:active { transform: translateY(1px); }
.nx-cta:disabled { opacity: .4; box-shadow: none; filter: none; cursor: not-allowed; }

/* The migration ring's travelling sheen — a conic gradient rotated by an
   animated custom property, masked to the ring's own band. The property is
   registered so the browser can interpolate the angle; without that a
   keyframe on an unregistered custom property cannot tween per spec and
   would flip at the end, which is a safe degrade rather than a break. */


.nx-mig-sweep {
  background: conic-gradient(from var(--nx-mig-spin),
    rgba(196,166,255,0) 0deg, rgba(196,166,255,0) 250deg,
    rgba(196,166,255,.55) 330deg, rgba(196,166,255,0) 360deg);
  -webkit-mask: radial-gradient(circle, transparent 0 68px, #000 68px 82px, transparent 82px);
  mask: radial-gradient(circle, transparent 0 68px, #000 68px 82px, transparent 82px);
  animation: nx-mig-spin 2.6s linear infinite;
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) { .nx-mig-sweep { animation: none; opacity: .35; } }

/* The small merchandising pill on a search result ("Most Popular",
   "Save 33%") — same sweep, chip-sized. */
.nx-tagpill {
  display: inline-flex; align-items: center; border-radius: 8px;
  padding: 3px 9px; font-size: 11.5px; font-weight: 700; color: #fff;
  background: linear-gradient(100deg, #6d3ff0, #b93ce8);
  box-shadow: 0 0 16px -6px rgba(160, 60, 240, .9);
}


/* ── ticket thread: message bubble entrance ───────────────────────────
   Plays once when a bubble first mounts (a genuinely new message,
   never a poll re-render of one already on screen — React keys the list
   by message id, so an unchanged bubble never remounts). */

.nx-msg-in{ animation: nx-msg-in .28s ease-out both; }
@media (prefers-reduced-motion: reduce){
  .nx-msg-in{ animation: none; }
}

/* ── sidebar: rest icons stay lit, just quieter ──────────────────────────
   Every .nx-ico in the rail keeps its own real tone and glow — this was
   never "off vs on": the rail had NO rest/active distinction at all before
   Second round, same lesson taken further: even WITH the dot, a page where
   every row happens to be Normal/"With support" (the common case) is still
   all slate, and "unlit dot + plain text" reads as no styling at all rather
   than a deliberate quiet state — there is nothing on screen to prove a
   design decision was made here. Light communicates "needs attention" for
   the coloured tones; slate instead gets a small amount of actual SHAPE (a
   thin chip: border + faint fill) so it reads as a considered, calm badge —
   never a glow, that would put attention back on a state that has none. */
.nx-tag{
  position: relative; display: inline-flex; align-items: center; gap: 8px;
  padding: 2px 4px; color: #fff; font-weight: 650; white-space: nowrap;
}
.nx-tag::before{
  content: ""; position: absolute; inset: -10px -14px -10px -6px; z-index: -1;
  pointer-events: none; filter: blur(16px); border-radius: 999px;
  background: radial-gradient(70% 100% at 0% 50%, var(--g), transparent 75%);
  opacity: .55;
}
.nx-tag-dot{ width: 6px; height: 6px; border-radius: 999px; background: var(--g); flex: none; box-shadow: 0 0 8px 1px var(--g); }
.nx-tag-amber{ --g: var(--color-amber); }
.nx-tag-rose { --g: var(--color-rose); }
.nx-tag-cyan { --g: var(--color-cyan); }
.nx-tag-mint { --g: var(--color-mint); }
/* No --g, deliberately: a glow colour here would put light back on a tone
   whose whole point is staying quiet. Shape instead of light: a thin chip. */
.nx-tag-slate{
  color: var(--color-tx-dim);
  padding: 2px 9px 2px 7px;
  border-radius: 999px;
  background: rgba(127,154,208,.08);
  border: 1px solid rgba(127,154,208,.20);
}
.nx-tag-slate::before{ content: none; }
.nx-tag-slate .nx-tag-dot{ background: var(--color-tx-dim); box-shadow: none; }

/* Pulse — reserved for states something is actually waiting on (see the
   `pulse` flags on SupportView's STATUS/PRIORITY maps). A slow, soft
   breathing cycle, not a hard blink: several of these can be on screen in
   one table at once, and a harsher pulse would read as the whole table
   alarming rather than a handful of rows asking for a look. */

