import type { ExpiryState } from "@/lib/nx/domain-lifecycle";

/* Small presentational pieces shared by the domains list, search and detail
   screens. Token colours only (`--color-mint/amber/rose/cyan/...`), so every
   one of them has a real light-mode value. */

export type Tone = "mint" | "amber" | "rose" | "cyan" | "violet" | "slate";

const PILL: Record<Tone, string> = {
  mint: "border-mint/35 bg-mint/10 text-mint",
  amber: "border-amber/40 bg-amber/10 text-amber",
  rose: "border-rose/40 bg-rose/10 text-rose",
  cyan: "border-cyan/40 bg-cyan/10 text-cyan",
  violet: "border-violet/40 bg-violet/10 text-violet",
  slate: "border-rim-hi bg-well text-tx-dim",
};
const DOT: Record<Tone, string> = {
  mint: "bg-mint", amber: "bg-amber", rose: "bg-rose", cyan: "bg-cyan", violet: "bg-violet", slate: "bg-tx-faint",
};

export function Pill({ tone, children, pulse = false, className = "" }: { tone: Tone; children: React.ReactNode; pulse?: boolean; className?: string }) {
  return (
    <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border px-2.5 py-[3px] text-[12px] font-semibold ${PILL[tone]} ${className}`}>
      <span className={`h-1.5 w-1.5 flex-none rounded-full ${DOT[tone]} ${pulse ? "motion-safe:animate-pulse" : ""}`} aria-hidden />
      {children}
    </span>
  );
}

export const DOMAIN_STATUS: Record<string, { label: string; tone: Tone; pulse?: boolean }> = {
  ACTIVE: { label: "Active", tone: "mint" },
  PENDING: { label: "Registering", tone: "cyan", pulse: true },
  TRANSFER_PENDING: { label: "Transferring in", tone: "cyan", pulse: true },
  TRANSFER_FAILED: { label: "Transfer failed", tone: "rose" },
  EXPIRED: { label: "Expired", tone: "rose" },
  FAILED: { label: "Failed", tone: "rose" },
};

export function statusMeta(status: string) {
  return DOMAIN_STATUS[status] ?? { label: status.toLowerCase().replace(/_/g, " "), tone: "slate" as Tone };
}

export function expiryTone(e: ExpiryState): Tone {
  return e.tone === "ok" ? "mint" : e.tone === "soon" ? "amber" : e.tone === "urgent" || e.tone === "expired" ? "rose" : "slate";
}

/** A thin bar showing how much of the year is left before renewal. */
export function ExpiryMeter({ state, className = "" }: { state: ExpiryState; className?: string }) {
  const tone = expiryTone(state);
  const fill = tone === "mint" ? "bg-mint" : tone === "amber" ? "bg-amber" : tone === "rose" ? "bg-rose" : "bg-tx-faint";
  const pct = state.tone === "none" ? 0 : Math.max(state.tone === "expired" ? 0 : 4, Math.round(state.fraction * 100));
  return (
    <span className={`block h-1 w-full overflow-hidden rounded-full bg-rim-soft ${className}`} aria-hidden>
      <span className={`block h-full rounded-full ${fill}`} style={{ width: `${pct}%` }} />
    </span>
  );
}

/** "Dec 12, 2026", fixed to UTC so the server and the browser agree. */
export function fmtDate(iso: string | Date): string {
  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
}

/* DNS record type chips: one hue per family so a long table scans by type. */
const TYPE_TONE: Record<string, string> = {
  A: "text-blue border-blue/40 bg-blue/10",
  AAAA: "text-blue border-blue/40 bg-blue/10",
  ALIAS: "text-blue border-blue/40 bg-blue/10",
  CNAME: "text-violet border-violet/40 bg-violet/10",
  MX: "text-amber border-amber/40 bg-amber/10",
  TXT: "text-cyan border-cyan/40 bg-cyan/10",
  NS: "text-mint border-mint/40 bg-mint/10",
  SRV: "text-tx-dim border-rim-hi bg-well",
};
export function TypeChip({ type }: { type: string }) {
  return (
    <span className={`inline-grid min-w-[52px] place-items-center rounded-[7px] border px-1.5 py-[3px] font-mono text-[11.5px] font-bold ${TYPE_TONE[type] ?? TYPE_TONE.SRV}`}>
      {type}
    </span>
  );
}

/** Domain name with the extension set apart, so .com vs .co reads at a glance. */
export function DomainName({ name, className = "" }: { name: string; className?: string }) {
  const dot = name.indexOf(".");
  if (dot <= 0) return <span className={className}>{name}</span>;
  return (
    <span className={className}>
      {name.slice(0, dot)}
      <span className="text-tx-dim">{name.slice(dot)}</span>
    </span>
  );
}

