"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { fmtMoney } from "@/components/ui/primitives";
import { Icon } from "@/components/nx/Icon";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { tldGroupsFor, type TldGroup } from "@/lib/nx/tld-groups";
import type { DomainCheckResult } from "@/components/customer/DomainSearch";
import { DomainName, Pill } from "./DomainBits";

type ApiResponse = {
  exact?: DomainCheckResult | null;
  results?: DomainCheckResult[];
  error?: string;
  /** Set by the sandbox: these are sample results, not a live lookup. */
  demo?: boolean;
  retryAfterSec?: number;
};

export type CartItem = { domain: string; priceCents: number };
export type ResultFilter = "all" | TldGroup | "sale";
export type ResultSort = "price-asc" | "price-desc" | "name";

const FILTERS: { key: ResultFilter; label: string }[] = [
  { key: "all", label: "All" },
  { key: "popular", label: "Popular" },
  { key: "business", label: "Business" },
  { key: "country", label: "Country" },
  { key: "new", label: "New" },
  { key: "sale", label: "On sale" },
];

/** A real discount, straight off the live quote: the first-year price is below
 *  what it renews at. Never an invented "sale". */
export function salePercent(r: DomainCheckResult): number | null {
  if (r.priceCents == null || r.renewCents == null) return null;
  if (r.renewCents <= r.priceCents) return null;
  return Math.round((1 - r.priceCents / r.renewCents) * 100);
}

function matchesFilter(r: DomainCheckResult, f: ResultFilter): boolean {
  if (f === "all") return true;
  if (f === "sale") return salePercent(r) !== null;
  return tldGroupsFor(r.tld).includes(f);
}

const canBuy = (r: DomainCheckResult) => r.status === "available" && !r.premium && r.priceCents !== null;

/** Indicative "from" prices off the curated catalog — shown before anything is
 *  typed. A live search always replaces them with the real quote. */
const QUICK_PICKS = [".com", ".net", ".org", ".io", ".co", ".app", ".dev", ".ai"]
  .map((tld) => POPULAR_TLDS.find((t) => t.tld === tld))
  .filter((t): t is { tld: string; fromCents: number } => Boolean(t));

/** Keep what a customer types to characters a domain can contain. */
function cleanQuery(raw: string): string {
  return raw.trim().toLowerCase().replace(/^https?:\/\//, "").replace(/^www\./, "").replace(/\/.*$/, "").replace(/[^a-z0-9.-]/g, "");
}

const DEBOUNCE_MS = 550;

/**
 * The domains page's search. Availability is checked as you type (debounced,
 * so one pause is one lookup; the endpoint is rate-limited and cached
 * server-side), the exact name you typed is pinned on top with its first-year
 * AND renewal price side by side, and every other extension is listed under it.
 *
 * Results render inline — no modal — so the page, the list of domains you
 * already own and the mobile layout all stay where they are.
 */
export function DomainFinder({ configured, sandbox = false }: { configured: boolean; sandbox?: boolean }) {
  const searchable = configured || sandbox;
  const [q, setQ] = useState("");
  const [ran, setRan] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exact, setExact] = useState<DomainCheckResult | null>(null);
  const [results, setResults] = useState<DomainCheckResult[]>([]);
  const [demo, setDemo] = useState(false);
  const [filter, setFilter] = useState<ResultFilter>("all");
  const [sort, setSort] = useState<ResultSort>("price-asc");
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showAll, setShowAll] = useState(false);
  const reqId = useRef(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const runSearch = useCallback(async (raw: string) => {
    const query = cleanQuery(raw);
    if (query.length < 2) return;
    if (timer.current) clearTimeout(timer.current);
    const id = ++reqId.current;
    setRan(query);
    setLoading(true);
    setError(null);
    setShowAll(false);
    try {
      const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { cache: "no-store" });
      const json: ApiResponse = await res.json();
      if (id !== reqId.current) return; // a newer search already superseded this one
      if (res.status === 429) {
        setError(`You're searching very quickly — try again in ${json.retryAfterSec ?? 30} seconds.`);
      } else {
        setError(json.error ?? null);
      }
      setExact(json.exact ?? null);
      setResults(Array.isArray(json.results) ? json.results : []);
      setDemo(Boolean(json.demo));
    } catch {
      if (id !== reqId.current) return;
      setError("Search failed. Check your connection and try again.");
      setExact(null);
      setResults([]);
    } finally {
      if (id === reqId.current) setLoading(false);
    }
  }, []);

  // Instant search: one lookup per pause in typing, never per keystroke.
  useEffect(() => {
    if (!searchable) return;
    const query = cleanQuery(q);
    if (timer.current) clearTimeout(timer.current);
    if (query.length < 3 || query === ran) return;
    timer.current = setTimeout(() => void runSearch(query), DEBOUNCE_MS);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [q, ran, runSearch, searchable]);

  const clear = () => {
    reqId.current++;
    setQ(""); setRan(null); setExact(null); setResults([]); setError(null); setLoading(false); setDemo(false);
  };

  const addToCart = (r: DomainCheckResult) => {
    if (r.priceCents == null) return;
    setCart((c) => (c.some((x) => x.domain === r.domain) ? c : [...c, { domain: r.domain, priceCents: r.priceCents! }]));
  };
  const removeFromCart = (domain: string) => setCart((c) => c.filter((x) => x.domain !== domain));
  const inCart = (d: string) => cart.some((c) => c.domain === d);
  const totalCents = cart.reduce((n, c) => n + c.priceCents, 0);

  // The exact typed domain stays pinned whatever the sort is. When only a base
  // name was typed, the best available .com (or cheapest available) is featured.
  const others = useMemo(() => (exact ? results.filter((r) => r.domain !== exact.domain) : results), [exact, results]);
  const featured = exact ?? others.find((r) => r.tld === "com") ?? null;
  const rest = useMemo(() => {
    const list = others.filter((r) => r.domain !== featured?.domain && matchesFilter(r, filter));
    return [...list].sort((a, b) => {
      // Available first, then the chosen order.
      const av = canBuy(a) ? 0 : 1, bv = canBuy(b) ? 0 : 1;
      if (av !== bv) return av - bv;
      if (sort === "name") return a.domain.localeCompare(b.domain);
      const ap = a.priceCents ?? Number.MAX_SAFE_INTEGER, bp = b.priceCents ?? Number.MAX_SAFE_INTEGER;
      return sort === "price-desc" ? bp - ap : ap - bp;
    });
  }, [others, featured, filter, sort]);
  const counts = (f: ResultFilter) => others.filter((r) => r.domain !== featured?.domain && matchesFilter(r, f)).length;
  const visible = showAll ? rest : rest.slice(0, 8);
  const hasResults = ran !== null && (featured !== null || others.length > 0);

  const pickTld = (tld: string) => {
    const base = cleanQuery(q).split(".")[0] || "";
    if (!base) { setQ(tld.replace(/^\./, "") === tld ? tld : ""); document.getElementById("nx-domain-q")?.focus(); return; }
    setQ(base + tld);
    void runSearch(base + tld);
  };

  return (
    <section aria-labelledby="nx-find-h" className="card relative overflow-hidden rounded-[20px] p-0">
      <span aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,var(--color-blue),var(--color-violet),var(--color-brand-c),transparent)] opacity-70" />
      <div className="p-5 sm:p-7">
        <h2 id="nx-find-h" className="text-[22px] font-extrabold tracking-[-0.025em] text-white sm:text-[26px]">
          Find your <span className="grad-text">perfect domain</span>
        </h2>
        <p className="mt-1 text-[13.5px] text-tx-dim">
          Type a name. We check availability live as you type, with the first-year and renewal price for every extension.
        </p>

        <form
          role="search"
          className="mt-5 flex flex-col gap-2.5 sm:flex-row"
          onSubmit={(e) => { e.preventDefault(); void runSearch(q); }}
        >
          <label htmlFor="nx-domain-q" className="sr-only">Domain name</label>
          <div className="group relative flex-1">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-tx-faint transition-colors group-focus-within:text-violet">
              <Icon name="search" size={15} tone="inherit" />
            </span>
            <input
              id="nx-domain-q"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              disabled={!searchable}
              placeholder={searchable ? "yourbrand or yourbrand.com" : "Domain search unavailable"}
              autoComplete="off"
              autoCapitalize="none"
              spellCheck={false}
              inputMode="url"
              aria-describedby="nx-domain-status"
              className="h-[56px] w-full rounded-[14px] border border-rim-hi bg-well pl-12 pr-11 text-[16px] font-semibold text-white outline-none transition placeholder:font-normal placeholder:text-tx-faint focus:border-violet focus:shadow-[0_0_0_4px_color-mix(in_srgb,var(--color-violet)_18%,transparent)] disabled:opacity-60"
            />
            {q && (
              <button type="button" onClick={clear} aria-label="Clear search"
                      className="absolute right-3 top-1/2 grid h-8 w-8 -translate-y-1/2 place-items-center rounded-[9px] text-tx-faint transition hover:bg-hover hover:text-white">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" aria-hidden><path d="M18 6 6 18M6 6l12 12" /></svg>
              </button>
            )}
          </div>
          <button type="submit" disabled={!searchable || cleanQuery(q).length < 2} className="nx-cta h-[56px] flex-none px-8 text-[15px]">
            {loading ? "Checking…" : "Search"}
          </button>
        </form>

        <p id="nx-domain-status" role="status" aria-live="polite" className="sr-only">
          {loading ? "Checking availability" : ran && featured ? `${featured.domain} is ${featured.status === "available" ? "available" : featured.status === "taken" ? "taken" : "unverified"}` : ""}
        </p>

        {!searchable && (
          <div className="mt-4 rounded-[12px] border border-amber/35 bg-amber/10 px-4 py-3 text-[13px] text-amber">
            Domain registration isn&apos;t switched on for your account yet. Domains you already own stay fully manageable below.
          </div>
        )}

        {searchable && ran === null && (
          <>
            <div className="mt-4 grid grid-cols-4 gap-2 sm:grid-cols-8">
              {QUICK_PICKS.map((t) => (
                <button
                  key={t.tld}
                  type="button"
                  onClick={() => pickTld(t.tld)}
                  className="group flex flex-col items-start rounded-[12px] border border-rim bg-well px-3 py-2 text-left transition hover:-translate-y-0.5 hover:border-violet/60 focus-visible:outline-2 focus-visible:outline-offset-2"
                >
                  <span className="text-[14.5px] font-bold text-white">{t.tld}</span>
                  <span className="text-[11.5px] text-tx-faint">from <span className="font-semibold text-tx-dim group-hover:text-white">{fmtMoney(t.fromCents)}</span></span>
                </button>
              ))}
            </div>
            <div className="mt-4 flex flex-wrap items-center gap-x-5 gap-y-2 text-[12.5px] text-tx-dim">
              {/* All three are real: WHOIS privacy and DNS are per-domain
                  controls on the manage page; the inbox is a real subscription. */}
              {[
                { icon: "shieldcheck", t: "Free WHOIS privacy" },
                { icon: "server2", t: "Free DNS management" },
                { icon: "envelope", t: "Free business inbox" },
              ].map((f) => (
                <span key={f.t} className="flex items-center gap-1.5">
                  <Icon name={f.icon} size={13} tone="inherit" className="text-mint" />
                  {f.t}
                </span>
              ))}
              <Link href="/domains" className="ml-auto font-semibold text-violet hover:underline">All extensions &amp; prices →</Link>
            </div>
          </>
        )}
      </div>

      {searchable && ran !== null && (
        <div className="border-t border-rim-soft bg-well/40 p-4 sm:p-6">
          {demo && (
            <p className="mb-3 rounded-[10px] border border-amber/35 bg-amber/10 px-3.5 py-2 text-[12px] text-amber">
              Sample results. Nothing was looked up in this environment, so prices and availability are illustrative.
            </p>
          )}

          {loading && !hasResults && <ResultSkeleton />}

          {!loading && error && (
            <p className="rounded-[12px] border border-rose/35 bg-rose/10 px-4 py-3 text-[13px] text-rose">{error}</p>
          )}

          {!error && hasResults && (
            <div className={loading ? "opacity-60 transition-opacity" : "transition-opacity"}>
              {featured && (
                <FeaturedResult
                  r={featured}
                  exactTyped={!!exact}
                  added={inCart(featured.domain)}
                  onToggle={() => (inCart(featured.domain) ? removeFromCart(featured.domain) : addToCart(featured))}
                />
              )}

              {others.length > 0 && (
                <>
                  <div className="mt-5 flex flex-wrap items-center gap-2">
                    <span className="mr-1 text-[12px] font-bold uppercase tracking-[0.12em] text-tx-faint">More extensions</span>
                    <div className="-mx-1 flex max-w-full gap-1.5 overflow-x-auto px-1 pb-1 sm:flex-wrap sm:overflow-visible" role="group" aria-label="Filter extensions">
                      {FILTERS.map((f) => {
                        const n = f.key === "all" ? counts("all") : counts(f.key);
                        const on = filter === f.key;
                        return (
                          <button
                            key={f.key}
                            type="button"
                            aria-pressed={on}
                            onClick={() => setFilter(f.key)}
                            disabled={n === 0 && f.key !== "all"}
                            className={
                              "flex-none rounded-full border px-3 py-1 text-[12.5px] font-semibold transition disabled:opacity-35 " +
                              (on ? "border-violet/60 bg-violet/15 text-white" : "border-rim bg-surface text-tx-dim hover:text-white")
                            }
                          >
                            {f.label} <span className="text-tx-faint">{n}</span>
                          </button>
                        );
                      })}
                    </div>
                    <select
                      value={sort}
                      onChange={(e) => setSort(e.target.value as ResultSort)}
                      aria-label="Sort extensions"
                      className="ml-auto h-[32px] rounded-[9px] border border-rim bg-surface px-2.5 text-[12.5px] text-tx-dim outline-none"
                    >
                      <option value="price-asc">Price: low to high</option>
                      <option value="price-desc">Price: high to low</option>
                      <option value="name">Name: A–Z</option>
                    </select>
                  </div>

                  {rest.length === 0 ? (
                    <p className="py-6 text-center text-[13px] text-tx-dim">No extensions in this group for that name.</p>
                  ) : (
                    <ul className="mt-3 grid gap-2 md:grid-cols-2">
                      {visible.map((r) => (
                        <ResultRow
                          key={r.domain}
                          r={r}
                          added={inCart(r.domain)}
                          onToggle={() => (inCart(r.domain) ? removeFromCart(r.domain) : addToCart(r))}
                        />
                      ))}
                    </ul>
                  )}
                  {rest.length > 8 && (
                    <button type="button" onClick={() => setShowAll((v) => !v)} className="mt-3 w-full rounded-[11px] border border-rim bg-surface py-2 text-[12.5px] font-semibold text-tx-dim transition hover:text-white">
                      {showAll ? "Show fewer" : `Show all ${rest.length} extensions`}
                    </button>
                  )}
                </>
              )}
            </div>
          )}

          {!loading && !error && ran !== null && !hasResults && (
            <p className="py-6 text-center text-[13px] text-tx-dim">No results for “{ran}”. Try a shorter name or another extension.</p>
          )}
        </div>
      )}

      {cart.length > 0 && (
        <div className="sticky bottom-0 z-10 flex flex-wrap items-center gap-3 border-t border-violet/35 bg-surface/95 px-4 py-3 backdrop-blur sm:px-6">
          <span className="grid h-8 min-w-8 place-items-center rounded-full bg-violet/15 px-2 text-[13px] font-bold text-violet">{cart.length}</span>
          <span className="min-w-0 flex-1">
            <span className="block truncate text-[13px] font-semibold text-white">{cart.map((c) => c.domain).join(", ")}</span>
            <span className="block text-[11.5px] text-tx-faint">
              {fmtMoney(totalCents)} first year{cart.length > 1 ? " in total. Registered one at a time, starting with " + cart[0].domain + "." : "."}
            </span>
          </span>
          <button type="button" onClick={() => setCart([])} className="text-[12px] font-semibold text-tx-dim hover:text-white">Clear</button>
          <Link href={`/dashboard/domains/register?domain=${encodeURIComponent(cart[0].domain)}`} className="nx-cta h-10 px-5 text-[13.5px]">
            Continue →
          </Link>
        </div>
      )}
    </section>
  );
}

function PriceBlock({ r, big = false }: { r: DomainCheckResult; big?: boolean }) {
  const off = salePercent(r);
  return (
    <span className="flex flex-col items-end text-right">
      <span className="flex items-baseline gap-1.5">
        {off !== null && <span className="nx-tagpill !px-1.5 !py-px !text-[10.5px]">Save {off}%</span>}
        <span className={(big ? "text-[24px]" : "text-[16px]") + " num leading-none text-white"}>{fmtMoney(r.priceCents!)}</span>
        <span className="text-[11.5px] text-tx-faint">1st yr</span>
      </span>
      {r.renewCents != null && (
        <span className={"mt-1 whitespace-nowrap text-[12px] " + (r.renewCents > (r.priceCents ?? 0) ? "font-semibold text-tx-dim" : "text-tx-faint")}>
          Renews at {fmtMoney(r.renewCents)}/yr
        </span>
      )}
    </span>
  );
}

function statusPill(r: DomainCheckResult) {
  if (r.premium) return <Pill tone="amber">Premium</Pill>;
  if (r.status === "available") return <Pill tone="mint">Available</Pill>;
  if (r.status === "taken") return <Pill tone="slate">Taken</Pill>;
  return <Pill tone="amber">Couldn&apos;t check</Pill>;
}

function FeaturedResult({ r, exactTyped, added, onToggle }: { r: DomainCheckResult; exactTyped: boolean; added: boolean; onToggle: () => void }) {
  const buy = canBuy(r);
  return (
    <div
      className={
        "relative overflow-hidden rounded-[16px] border p-4 sm:p-5 " +
        (buy ? "border-mint/40 bg-[linear-gradient(120deg,color-mix(in_srgb,var(--color-mint)_9%,var(--color-surface)),var(--color-surface)_60%)]" : "border-rim-hi bg-surface")
      }
    >
      <div className="flex flex-wrap items-center gap-x-4 gap-y-3">
        <span className="flex min-w-0 flex-1 flex-col gap-1.5">
          <span className="flex flex-wrap items-center gap-2">
            {statusPill(r)}
            {!exactTyped && <span className="text-[11.5px] font-semibold uppercase tracking-[0.12em] text-tx-faint">Top pick</span>}
          </span>
          <DomainName name={r.domain} className="block truncate text-[22px] font-extrabold tracking-[-0.025em] text-white sm:text-[26px]" />
          <span className="text-[12.5px] text-tx-dim">
            {buy
              ? "Free WHOIS privacy and DNS included. Cancel auto-renew any time."
              : r.premium
                ? "Premium names are priced by the registry and can't be registered here."
                : r.status === "taken"
                  ? "Someone already owns this name. If it's yours, you can transfer it in."
                  : "We couldn't confirm this one right now. Try again in a moment."}
          </span>
        </span>
        {buy && <PriceBlock r={r} big />}
        <span className="flex w-full flex-none gap-2 sm:w-auto">
          {buy ? (
            <>
              <Link href={`/dashboard/domains/register?domain=${encodeURIComponent(r.domain)}`} className="nx-cta h-11 flex-1 px-6 text-[14px] sm:flex-none">
                Register
              </Link>
              <button
                type="button"
                onClick={onToggle}
                aria-pressed={added}
                className={"grid h-11 w-11 flex-none place-items-center rounded-[10px] border transition " + (added ? "border-mint/50 bg-mint/10 text-mint" : "border-rim-hi bg-surface text-tx-dim hover:text-white")}
                aria-label={added ? `Remove ${r.domain} from your list` : `Add ${r.domain} to your list`}
                title={added ? "In your list" : "Add to list"}
              >
                <Icon name={added ? "checkcircle" : "cart"} size={15} tone="inherit" />
              </button>
            </>
          ) : r.status === "taken" ? (
            <Link href={`/dashboard/domains/transfer?domain=${encodeURIComponent(r.domain)}`} className="btn-secondary h-11 flex-1 justify-center px-5 text-[13.5px] sm:flex-none">
              Transfer it in
            </Link>
          ) : null}
        </span>
      </div>
    </div>
  );
}

function ResultRow({ r, added, onToggle }: { r: DomainCheckResult; added: boolean; onToggle: () => void }) {
  const buy = canBuy(r);
  return (
    <li className={"flex items-center gap-3 rounded-[13px] border px-3.5 py-3 transition " + (buy ? "border-rim bg-surface hover:border-rim-hi" : "border-rim-soft bg-transparent")}>
      <span className="flex min-w-0 flex-1 flex-col gap-1">
        <DomainName name={r.domain} className={"block truncate text-[14.5px] font-bold " + (buy ? "text-white" : "text-tx-faint")} />
        <span>{statusPill(r)}</span>
      </span>
      {buy ? (
        <>
          <PriceBlock r={r} />
          <button
            type="button"
            onClick={onToggle}
            aria-pressed={added}
            aria-label={added ? `Remove ${r.domain} from your list` : `Add ${r.domain} to your list`}
            className={"grid h-9 w-9 flex-none place-items-center rounded-[9px] border transition " + (added ? "border-mint/50 bg-mint/10 text-mint" : "border-rim-hi bg-well text-tx-dim hover:border-violet/60 hover:text-white")}
          >
            <Icon name={added ? "checkcircle" : "cart"} size={13} tone="inherit" />
          </button>
        </>
      ) : r.status === "taken" ? (
        <Link href={`/dashboard/domains/transfer?domain=${encodeURIComponent(r.domain)}`} className="text-[12.5px] font-semibold text-tx-dim hover:text-white">
          Transfer →
        </Link>
      ) : null}
    </li>
  );
}

function ResultSkeleton() {
  return (
    <div aria-hidden>
      <div className="h-[110px] rounded-[16px] border border-rim bg-surface p-5">
        <span className="skeleton block h-4 w-20" />
        <span className="skeleton mt-3 block h-6 w-56" />
        <span className="skeleton mt-3 block h-3 w-72 max-w-full" />
      </div>
      <div className="mt-5 grid gap-2 md:grid-cols-2">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="flex h-[62px] items-center justify-between rounded-[13px] border border-rim-soft bg-surface px-4">
            <span className="skeleton h-3.5 w-36" />
            <span className="skeleton h-3.5 w-16" />
          </div>
        ))}
      </div>
    </div>
  );
}

