      aria-label={label}
      onClick={onChange}
      className={
        "grid h-[18px] w-[18px] flex-none place-items-center rounded-[5px] border transition focus-visible:outline-2 focus-visible:outline-offset-2 " +
        (checked ? "border-violet bg-violet" : "border-rim-hi bg-well hover:border-violet/60")
      }
    >
      {checked && (
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
          <path d="M20 6 9 17l-5-5" />
        </svg>
      )}
