    start(async () => {
      for (const id of ids) await toggleDomainAutoRenew(id);
      setSelected([]);
      router.refresh();
    });
  }

  if (rows.length === 0) {
    return (
      <section className="card flex flex-col items-center rounded-[18px] px-6 py-10 text-center sm:py-12">
        <DomainEmptyArt className="h-auto w-full max-w-[340px]" />
        <h2 className="mt-4 text-[20px] font-extrabold tracking-[-0.02em] text-white">No domains yet</h2>
        <p className="mt-1.5 max-w-[46ch] text-[13.5px] leading-relaxed text-tx-dim">
          Search for a name above and register it in a couple of minutes, or bring a domain you already own over to Nxeon.
        </p>
        <div className="mt-5 flex flex-wrap justify-center gap-2.5">
          <a href="#nx-domain-q" className="nx-cta h-10 px-5 text-[13.5px]">Search for a domain</a>
          <Link href="/dashboard/domains/transfer" className="btn-secondary h-10 px-5 text-[13px]">Transfer one in</Link>
        </div>
      </section>
    );
  }

  return (
    <section className="card rounded-[18px] p-0" aria-labelledby="nx-mine-h">
      <div className="flex flex-wrap items-center justify-between gap-3 px-4 pt-5 sm:px-6">
        <div>
          <h2 id="nx-mine-h" className="text-[18px] font-extrabold tracking-[-0.02em] text-white">Your domains</h2>
          <p className="mt-0.5 text-[12.5px] text-tx-dim">{rows.length} domain{rows.length === 1 ? "" : "s"} on your account</p>
        </div>
        <div className="flex w-full flex-wrap items-center gap-2 sm:w-auto">
          <label className="flex h-[38px] min-w-0 flex-1 items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 focus-within:border-violet sm:w-[220px] sm:flex-none">
            <Icon name="search" size={13} tone="inherit" className="flex-none text-tx-faint" />
            <span className="sr-only">Filter your domains</span>
            <input
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Filter by name"
              className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-tx-faint"
            />
          </label>
          {configured && (
            <a href="#nx-domain-q" className="nx-cta h-[38px] px-4 text-[13px]">+ Register</a>
          )}
        </div>
      </div>

      <div className="-mx-px mt-4 flex gap-1.5 overflow-x-auto px-4 pb-1 sm:px-6" role="group" aria-label="Filter by status">
        {FILTERS.map((f) => {
          const n = count(f.key);
          if (f.key !== "all" && n === 0) return null;
          const on = status === f.key;
          return (
            <button
              key={f.key}
              type="button"
              aria-pressed={on}
              onClick={() => setStatus(f.key)}
              className={
                "flex flex-none items-center gap-1.5 rounded-full border px-3 py-1 text-[12.5px] font-semibold transition " +
                (on ? "border-violet/60 bg-violet/15 text-white" : "border-rim bg-well text-tx-dim hover:text-white")
              }
            >
              {f.label}
              <span className={on ? "text-white/80" : "text-tx-faint"}>{n}</span>
            </button>
          );
        })}
      </div>

      {selected.length > 0 && (
        <div className="mx-4 mt-3 flex flex-wrap items-center gap-2 rounded-[11px] border border-violet/40 bg-violet/10 px-3.5 py-2 sm:mx-6" role="region" aria-label="Bulk actions">
          <span className="text-[12.5px] font-semibold text-white">{selected.length} selected</span>
          <button type="button" disabled={pending} onClick={() => bulkAutoRenew(true)} className="rounded-[8px] border border-rim-hi bg-surface px-3 py-1.5 text-[12px] font-semibold text-white disabled:opacity-50">
            Turn auto-renew on
          </button>
          <button type="button" disabled={pending} onClick={() => bulkAutoRenew(false)} className="rounded-[8px] border border-rim-hi bg-surface px-3 py-1.5 text-[12px] font-semibold text-white disabled:opacity-50">
            Turn auto-renew off
