                <col className="w-[44px]" />
                <col />
                <col className="w-[132px]" />
                <col className="w-[190px]" />
                <col className="w-[96px]" />
                <col className="w-[150px]" />
                <col className="w-[104px]" />
              </colgroup>
              <thead>
                <tr className="border-y border-rim-soft text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">
                  <th className="py-2.5 pl-6"><Checkbox checked={allShownSelected} onChange={toggleAll} label="Select all shown domains" /></th>
                  <th className="py-2.5 pr-4 font-bold">Domain</th>
                  <th className="py-2.5 pr-4 font-bold">Status</th>
                  <th className="py-2.5 pr-6 font-bold">Renews</th>
                  <th className="py-2.5 pr-4 font-bold">Auto-renew</th>
                  <th className="py-2.5 pr-4 font-bold">DNS &amp; email</th>
                  <th className="py-2.5 pr-6"><span className="sr-only">Actions</span></th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((d) => {
                  const meta = statusMeta(d.status);
                  return (
                    <tr key={d.id} className="group border-b border-rim-soft transition-colors last:border-0 hover:bg-hover">
                      <td className="py-3.5 pl-6 align-middle">
                        <Checkbox checked={selected.includes(d.id)} onChange={() => toggleOne(d.id)} label={`Select ${d.name}`} />
                      </td>
                      <td className="min-w-0 py-3.5 pr-4">
                        <Link href={`/dashboard/domains/${d.id}`} title={d.name} className="block truncate text-[14.5px] font-bold text-white hover:text-violet">
                          <DomainName name={d.name} />
                        </Link>
                        <span className="mt-1 flex min-w-0"><LinkedTo link={d.link} /></span>
                      </td>
                      <td className="py-3.5 pr-4"><Pill tone={meta.tone} pulse={meta.pulse}>{meta.label}</Pill></td>
                      <td className="py-3.5 pr-6"><Renewal d={d} now={now} /></td>
                      <td className="py-3.5 pr-4">
                        {d.status === "ACTIVE" || d.status === "EXPIRED" ? (
                          <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} domainName={d.name} />
                        ) : (
                          <span className="text-[12px] text-tx-faint">—</span>
                        )}
                      </td>
                      <td className="py-3.5 pr-4">
                        <span className="flex flex-col gap-1 text-[12.5px]">
                          <span className="flex items-center gap-1.5 text-tx-dim">
                            <Icon name="server2" size={11} tone="inherit" className="flex-none text-blue" />
                            {d.nameserverLabel}
                          </span>
                          <span className={"flex items-center gap-1.5 " + (d.emailEnabled ? "text-mint" : "text-tx-faint")}>
                            <Icon name="envelope" size={11} tone="inherit" className="flex-none" />
                            {d.emailEnabled ? "Email on" : "No email"}
                          </span>
                        </span>
                      </td>
                      <td className="py-3.5 pr-6 text-right">
                        <Link href={`/dashboard/domains/${d.id}`} className="inline-flex items-center gap-1 rounded-[9px] border border-rim-hi bg-surface px-3 py-1.5 text-[12.5px] font-semibold text-white transition hover:border-violet/60">
                          Manage <span aria-hidden>→</span>
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Phone + tablet: one card per domain. */}
          <ul className="mt-3 space-y-2.5 px-3 pb-4 sm:px-5 lg:hidden">
            {filtered.map((d) => {
              const meta = statusMeta(d.status);
              return (
                <li key={d.id} className="rounded-[15px] border border-rim bg-well p-3.5">
                  <div className="flex items-start gap-3">
                    <Checkbox checked={selected.includes(d.id)} onChange={() => toggleOne(d.id)} label={`Select ${d.name}`} />
                    <div className="min-w-0 flex-1">
                      <Link href={`/dashboard/domains/${d.id}`} className="block truncate text-[16px] font-bold text-white">
                        <DomainName name={d.name} />
                      </Link>
                      <div className="mt-1.5 flex flex-wrap items-center gap-2">
                        <Pill tone={meta.tone} pulse={meta.pulse}>{meta.label}</Pill>
                        <LinkedTo link={d.link} />
                      </div>
                    </div>
                  </div>
                  <div className="mt-3"><Renewal d={d} now={now} /></div>
                  <div className="mt-3 flex items-center gap-3 border-t border-rim-soft pt-3">
                    {d.status === "ACTIVE" || d.status === "EXPIRED" ? (
                      <span className="flex items-center gap-2 text-[12.5px] text-tx-dim">
                        <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} domainName={d.name} />
                        Auto-renew
                      </span>
                    ) : (
                      <span className="text-[12.5px] text-tx-faint">{d.nameserverLabel}</span>
                    )}
                    {d.renewCents != null && d.status === "ACTIVE" && (
                      <span className="text-[12px] text-tx-faint">{fmtMoney(d.renewCents)}/yr</span>
                    )}
                    <Link href={`/dashboard/domains/${d.id}`} className="ml-auto inline-flex h-9 items-center rounded-[9px] border border-rim-hi bg-surface px-3.5 text-[13px] font-semibold text-white">
                      Manage
                    </Link>
                  </div>
                </li>
              );
            })}
          </ul>
        </>
      )}
    </section>
  );
}

