input.content:
"use client";

import { useMemo, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
import { toggleDomainAutoRenew } from "@/lib/actions-domains";
import { expiryState } from "@/lib/nx/domain-lifecycle";
import type { DomainLink } from "@/lib/nx/domain-links";
import { DomainEmptyArt } from "@/components/nx/visual/DomainArt";
import { DomainName, ExpiryMeter, Pill, expiryTone, fmtDate, statusMeta } from "./DomainBits";

export type DomainRow = {
  id: string;
  name: string;
  status: string;
  expiresAtIso: string | null;
  autoRenew: boolean;
  /** "Nxeon DNS" when the domain is on our default nameservers, else "Custom". */
  nameserverLabel: string;
  emailEnabled: boolean;
  priceCents: number;
  /** Renewal price per year (the frozen renewal quote, else the first-year price). */
  renewCents?: number;
  /** The Nxeon service this domain is attached to, when there really is one. */
  link?: DomainLink | null;
};

type StatusFilter = "all" | "active" | "expiring" | "attention" | "progress";

const FILTERS: { key: StatusFilter; label: string }[] = [
  { key: "all", label: "All" },
  { key: "active", label: "Active" },
  { key: "expiring", label: "Expiring soon" },
  { key: "attention", label: "Needs attention" },
  { key: "progress", label: "In progress" },
];

function bucket(d: DomainRow, now: number): StatusFilter[] {
  const out: StatusFilter[] = ["all"];
  const e = expiryState(d.expiresAtIso, now);
  if (d.status === "ACTIVE") out.push("active");
  if (d.status === "ACTIVE" && (e.tone === "soon" || e.tone === "urgent")) out.push("expiring");
  if (["EXPIRED", "FAILED", "TRANSFER_FAILED"].includes(d.status) || e.tone === "expired") out.push("attention");
  if (d.status === "PENDING" || d.status === "TRANSFER_PENDING") out.push("progress");
  return out;
}

function Checkbox({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
      className={
        "grid h-[18px] w-[18px] flex-none place-items-center rounded-[5px] border transition focus-visible:outline-2 focus-visible:outline-offset-2 " +
        (checked ? "border-violet bg-violet" : "border-rim-hi bg-well hover:border-violet/60")
      }
    >
      {checked && (
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
          <path d="M20 6 9 17l-5-5" />
        </svg>
      )}
    </button>
  );
}

const LINK_ICON: Record<DomainLink["kind"], string> = { hosting: "globe2", website: "server2", server: "server2" };

function LinkedTo({ link }: { link: DomainLink | null | undefined }) {
  if (!link) return <span className="text-[12px] text-tx-faint">Not linked to a service</span>;
  return (
    <Link href={link.href} className="inline-flex max-w-full items-center gap-1.5 truncate rounded-full border border-rim bg-well px-2 py-[2px] text-[12px] font-semibold text-tx-dim transition hover:border-violet/50 hover:text-white">
      <Icon name={LINK_ICON[link.kind]} size={11} tone="inherit" className="flex-none text-violet" />
      <span className="truncate">{link.label}</span>
      {link.more > 0 && <span className="text-tx-faint">+{link.more}</span>}
    </Link>
  );
}

function Renewal({ d, now }: { d: DomainRow; now: number }) {
  const e = expiryState(d.expiresAtIso, now);
  if (!d.expiresAtIso) {
    return <span className="text-[12.5px] text-tx-faint">{d.status === "TRANSFER_PENDING" ? "Set when the transfer completes" : "—"}</span>;
  }
  const tone = expiryTone(e);
  const ink = tone === "rose" ? "text-rose" : tone === "amber" ? "text-amber" : "text-tx-dim";
  return (
    <span className="flex min-w-0 flex-col gap-1">
      <span className="flex items-baseline justify-between gap-2">
        <span className="text-[13px] font-semibold text-white" suppressHydrationWarning>{fmtDate(d.expiresAtIso)}</span>
        <span className={"whitespace-nowrap text-[11.5px] font-semibold " + ink} suppressHydrationWarning>{e.text}</span>
      </span>
      <ExpiryMeter state={e} />
    </span>
  );
}

export function DomainsTable({ rows, configured, now: nowProp }: { rows: DomainRow[]; configured: boolean; now?: number }) {
  const router = useRouter();
  // Fixed once so the server render and the first client render agree.
  const [now] = useState(() => nowProp ?? Date.now());
  const [q, setQ] = useState("");
  const [status, setStatus] = useState<StatusFilter>("all");
  const [selected, setSelected] = useState<string[]>([]);
  const [pending, start] = useTransition();

  const buckets = useMemo(() => new Map(rows.map((d) => [d.id, bucket(d, now)])), [rows, now]);
  const count = (f: StatusFilter) => rows.filter((d) => buckets.get(d.id)!.includes(f)).length;

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return rows.filter((d) => (!needle || d.name.toLowerCase().includes(needle)) && buckets.get(d.id)!.includes(status));
  }, [rows, q, status, buckets]);

  const allShownSelected = filtered.length > 0 && filtered.every((d) => selected.includes(d.id));
  const toggleAll = () => setSelected(allShownSelected ? [] : filtered.map((d) => d.id));
  const toggleOne = (id: string) => setSelected((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));

  // The one bulk action that genuinely exists behind the checkboxes: flip
  // auto-renew on every selected domain, through the same per-domain server
  // action the row switch uses.
  function bulkAutoRenew(target: boolean) {
    const ids = rows.filter((d) => selected.includes(d.id) && d.autoRenew !== target).map((d) => d.id);
    if (ids.length === 0) return;
    start(async () => {
      for (const id of ids) await toggleDomainAutoRenew(id);
      setSelected([]);
      router.refresh();
    });
  }

  if (rows.length === 0) {
    return (
      <section className="card flex flex-col items-center rounded-[18px] px-6 py-10 text-center sm:py-12">
        <DomainEmptyArt className="h-auto w-full max-w-[340px]" />
        <h2 className="mt-4 text-[20px] font-extrabold tracking-[-0.02em] text-white">No domains yet</h2>
        <p className="mt-1.5 max-w-[46ch] text-[13.5px] leading-relaxed text-tx-dim">
          Search for a name above and register it in a couple of minutes, or bring a domain you already own over to Nxeon.
        </p>
        <div className="mt-5 flex flex-wrap justify-center gap-2.5">
          {configured && <a href="#nx-domain-q" className="nx-cta h-10 px-5 text-[13.5px]">Search for a domain</a>}
          <Link href="/dashboard/domains/transfer" className="btn-secondary h-10 px-5 text-[13px]">Transfer one in</Link>
        </div>
      </section>
    );
  }

  return (
    <section className="card rounded-[18px] p-0" aria-labelledby="nx-mine-h">
      <div className="flex flex-wrap items-center justify-between gap-3 px-4 pt-5 sm:px-6">
        <div>
          <h2 id="nx-mine-h" className="text-[18px] font-extrabold tracking-[-0.02em] text-white">Your domains</h2>
          <p className="mt-0.5 text-[12.5px] text-tx-dim">{rows.length} domain{rows.length === 1 ? "" : "s"} on your account</p>
        </div>
        <label className="flex h-[38px] w-full min-w-0 items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 focus-within:border-violet sm:w-[240px]">
          <Icon name="search" size={13} tone="inherit" className="flex-none text-tx-faint" />
          <span className="sr-only">Filter your domains</span>
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Filter by name"
            className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-tx-faint"
          />
        </label>
      </div>

      <div className="mt-4 flex gap-1.5 overflow-x-auto px-4 pb-1 sm:px-6" role="group" aria-label="Filter by status">
        {FILTERS.map((f) => {
          const n = count(f.key);
          if (f.key !== "all" && n === 0) return null;
          const on = status === f.key;
          return (
            <button
              key={f.key}
              type="button"
              aria-pressed={on}
              onClick={() => setStatus(f.key)}
              className={
                "flex flex-none items-center gap-1.5 rounded-full border px-3 py-1 text-[12.5px] font-semibold transition " +
                (on ? "border-violet/60 bg-violet/15 text-white" : "border-rim bg-well text-tx-dim hover:text-white")
              }
            >
              {f.label}
              <span className="text-tx-faint">{n}</span>
            </button>
          );
        })}
      </div>

      {selected.length > 0 && (
        <div className="mx-4 mt-3 flex flex-wrap items-center gap-2 rounded-[11px] border border-violet/40 bg-violet/10 px-3.5 py-2 sm:mx-6" role="region" aria-label="Bulk actions">
          <span className="text-[12.5px] font-semibold text-white">{selected.length} selected</span>
          <button type="button" disabled={pending} onClick={() => bulkAutoRenew(true)} className="rounded-[8px] border border-rim-hi bg-surface px-3 py-1.5 text-[12px] font-semibold text-white disabled:opacity-50">
            Turn auto-renew on
          </button>
          <button type="button" disabled={pending} onClick={() => bulkAutoRenew(false)} className="rounded-[8px] border border-rim-hi bg-surface px-3 py-1.5 text-[12px] font-semibold text-white disabled:opacity-50">
            Turn auto-renew off
          </button>
          <button type="button" onClick={() => setSelected([])} className="ml-auto text-[12px] text-tx-dim hover:text-white">Clear</button>
        </div>
      )}

      {filtered.length === 0 ? (
        <p className="px-6 py-12 text-center text-[13px] text-tx-dim">No domains match that filter.</p>
      ) : (
        <>
          {/* Desktop: a real table, fixed columns so nothing runs off the card. */}
          <div className="mt-3 hidden lg:block">
            <table className="w-full table-fixed border-collapse text-left">
              <colgroup>
                <col className="w-[52px]" />
                <col />
                <col className="w-[148px]" />
                <col className="w-[200px]" />
                <col className="w-[104px]" />
                <col className="w-[132px]" />
                <col className="w-[112px]" />
              </colgroup>
              <thead>
                <tr className="border-y border-rim-soft text-[10.5px] uppercase tracking-[0.12em] text-tx-faint">
                  <th className="py-2.5 pl-6"><Checkbox checked={allShownSelected} onChange={toggleAll} label="Select all shown domains" /></th>
                  <th className="py-2.5 pr-4 font-bold">Domain</th>
                  <th className="py-2.5 pr-4 font-bold">Status</th>
                  <th className="py-2.5 pr-6 font-bold">Renews</th>
                  <th className="py-2.5 pr-4 font-bold">Auto-renew</th>
                  <th className="py-2.5 pr-4 font-bold">DNS · Email</th>
                  <th className="py-2.5 pr-6"><span className="sr-only">Actions</span></th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((d) => {
                  const meta = statusMeta(d.status);
                  return (
                    <tr key={d.id} className="border-b border-rim-soft transition-colors last:border-0 hover:bg-hover">
                      <td className="py-3.5 pl-6 align-middle">
                        <Checkbox checked={selected.includes(d.id)} onChange={() => toggleOne(d.id)} label={`Select ${d.name}`} />
                      </td>
                      <td className="min-w-0 py-3.5 pr-4">
                        <Link href={`/dashboard/domains/${d.id}`} title={d.name} className="block truncate text-[14.5px] font-bold text-white hover:text-violet">
                          <DomainName name={d.name} />
                        </Link>
                        <span className="mt-1 flex min-w-0"><LinkedTo link={d.link} /></span>
                      </td>
                      <td className="py-3.5 pr-4"><Pill tone={meta.tone} pulse={meta.pulse}>{meta.label}</Pill></td>
                      <td className="py-3.5 pr-6"><Renewal d={d} now={now} /></td>
                      <td className="py-3.5 pr-4">
                        {d.status === "ACTIVE" || d.status === "EXPIRED" ? (
                          <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} domainName={d.name} />
                        ) : (
                          <span className="text-[12px] text-tx-faint">—</span>
                        )}
                      </td>
                      <td className="py-3.5 pr-4">
                        <span className="flex flex-col gap-1 text-[12.5px]">
                          <span className="flex items-center gap-1.5 text-tx-dim">
                            <Icon name="server2" size={11} tone="inherit" className="flex-none text-blue" />
                            {d.nameserverLabel}
                          </span>
                          <span className={"flex items-center gap-1.5 " + (d.emailEnabled ? "text-mint" : "text-tx-faint")}>
                            <Icon name="envelope" size={11} tone="inherit" className="flex-none" />
                            {d.emailEnabled ? "Email on" : "No email"}
                          </span>
                        </span>
                      </td>
                      <td className="py-3.5 pr-6 text-right">
                        <Link href={`/dashboard/domains/${d.id}`} className="inline-flex items-center gap-1 rounded-[9px] border border-rim-hi bg-surface px-3 py-1.5 text-[12.5px] font-semibold text-white transition hover:border-violet/60">
                          Manage <span aria-hidden>→</span>
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Phone + tablet: one card per domain. */}
          <ul className="mt-3 space-y-2.5 px-3 pb-4 sm:px-5 lg:hidden">
            {filtered.map((d) => {
              const meta = statusMeta(d.status);
              return (
                <li key={d.id} className="rounded-[15px] border border-rim bg-well p-3.5">
                  <div className="flex items-start gap-3">
                    <span className="pt-1"><Checkbox checked={selected.includes(d.id)} onChange={() => toggleOne(d.id)} label={`Select ${d.name}`} /></span>
                    <div className="min-w-0 flex-1">
                      <Link href={`/dashboard/domains/${d.id}`} className="block truncate text-[16px] font-bold text-white">
                        <DomainName name={d.name} />
                      </Link>
                      <div className="mt-1.5 flex flex-wrap items-center gap-2">
                        <Pill tone={meta.tone} pulse={meta.pulse}>{meta.label}</Pill>
                        <LinkedTo link={d.link} />
                      </div>
                    </div>
                  </div>
                  <div className="mt-3"><Renewal d={d} now={now} /></div>
