"use client";

import { useRef, useState, type ReactNode, type KeyboardEvent } from "react";

type TabKey = "mine" | "transfers" | "ideas";

/**
 * The domains page's lower section. Every panel is a real section of THIS page
 * (transfers and the name generator used to send you off to their own routes,
 * leaving the page behind to do one step of the same job), so they are swapped
 * in place. Panels arrive already rendered from the server, so switching costs
 * nothing and nothing is refetched.
 *
 * A proper ARIA tablist: arrow keys move between tabs, Home/End jump.
 */
export function DomainsTabs({
  mine, transfers, ideas, mineCount,
}: {
  mine: ReactNode;
  transfers: ReactNode | null;
  ideas: ReactNode | null;
  mineCount: number;
}) {
  const tabs: { key: TabKey; label: string; badge?: number; panel: ReactNode | null }[] = [
    { key: "mine", label: "My domains", badge: mineCount, panel: mine },
    { key: "transfers", label: "Transfer in", panel: transfers },
    { key: "ideas", label: "Name ideas", panel: ideas },
  ];
  const shown = tabs.filter((t) => t.panel !== null);
  const [tab, setTab] = useState<TabKey>("mine");
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});

  const onKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    let next = -1;
    if (e.key === "ArrowRight") next = (i + 1) % shown.length;
    if (e.key === "ArrowLeft") next = (i - 1 + shown.length) % shown.length;
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = shown.length - 1;
    if (next < 0) return;
    e.preventDefault();
    setTab(shown[next].key);
    refs.current[shown[next].key]?.focus();
  };

  return (
    <div>
      <div role="tablist" aria-label="Domains" className="relative flex gap-6 overflow-x-auto border-b border-rim-soft">
        {shown.map((t, i) => (
          <button
            key={t.key}
            ref={(el) => { refs.current[t.key] = el; }}
            id={`nx-dt-${t.key}`}
            role="tab"
            type="button"
            aria-selected={tab === t.key}
            aria-controls={`nx-dp-${t.key}`}
            tabIndex={tab === t.key ? 0 : -1}
            onClick={() => setTab(t.key)}
            onKeyDown={(e) => onKey(e, i)}
            className={"nx-tab flex flex-none items-center gap-2 " + (tab === t.key ? "nx-tab-on" : "")}
          >
            {t.label}
            {t.badge !== undefined && t.badge > 0 && (
              <span className="rounded-full bg-violet/15 px-1.5 py-px text-[11px] font-bold text-violet">{t.badge}</span>
            )}
          </button>
        ))}
      </div>
      {shown.map((t) => (
        <div key={t.key} id={`nx-dp-${t.key}`} role="tabpanel" aria-labelledby={`nx-dt-${t.key}`} hidden={tab !== t.key} className="mt-5">
          {t.panel}
        </div>
      ))}
    </div>
  );
}

