import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, transfersAvailable } from "@/lib/registrar";
import { SANDBOX } from "@/lib/sandbox";
import { Icon } from "@/components/nx/Icon";
import { DomainsAurora } from "@/components/nx/DomainsAurora";
import { DomainTransferArt } from "@/components/nx/visual/DomainArt";
import { DomainsHero } from "@/components/customer/domains/DomainsHero";
import { DomainFinder } from "@/components/customer/domains/DomainFinder";
import { DomainsTable, type DomainRow } from "@/components/customer/domains/DomainsTable";
import { DomainsTabs } from "@/components/customer/domains/DomainsTabs";
import { DomainName } from "@/components/customer/domains/DomainBits";
import { DomainTransferInWizard } from "@/components/customer/DomainTransferInWizard";
import { DomainIdeaGenerator } from "@/components/customer/DomainIdeaGenerator";
import { findDomainInboxPlan } from "@/lib/domain-inbox-email";
import { loadDomainLinks } from "@/lib/domain-links";
import { expiryState } from "@/lib/nx/domain-lifecycle";

export const dynamic = "force-dynamic";

const HELP_LINKS = [
  { icon: "file", t: "Domain setup guide", s: "Step-by-step instructions", href: "/help" },
  { icon: "transfer2", t: "Transfer a domain", s: "Move a domain you own to Nxeon", href: "/dashboard/domains/transfer" },
  { icon: "server2", t: "DNS tools", s: "Look up and check records", href: "/tools" },
  { icon: "chatdots", t: "Contact support", s: "Our team is here to help", href: "/dashboard/support" },
];

function Figure({ value, label, tone = "tx", note }: { value: number; label: string; tone?: "tx" | "mint" | "amber" | "cyan"; note?: string }) {
  const ink = tone === "mint" ? "text-mint" : tone === "amber" ? "text-amber" : tone === "cyan" ? "text-cyan" : "text-white";
  return (
    <div className="flex min-w-0 flex-col gap-0.5 px-4 py-3.5 sm:px-5">
      <span className={"num text-[24px] leading-none " + ink}>{value}</span>
      <span className="text-[12px] text-tx-dim">{label}</span>
      {note && <span className="text-[11.5px] font-semibold text-tx-faint">{note}</span>}
    </div>
  );
}

export default async function DomainsPage() {
  const user = await requireUser();
  const configured = registrarConfigured();
  const canTransfer = transfersAvailable();
  const now = Date.now();

  const domains = await db.domain.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  // Real per-domain inbox state — a domain only counts as "Email on" when it
  // actually has a live mailbox, never just because a subscription row exists.
  const emailSubs = domains.length
    ? await db.emailSubscription.findMany({
        where: { userId: user.id, domainName: { in: domains.map((d) => d.name) }, status: { not: "CANCELLED" } },
        select: { domainName: true, mailboxes: { select: { status: true } } },
      })
    : [];
  const emailByDomain = new Map(
    emailSubs.map((s) => [s.domainName, s.mailboxes.some((m) => m.status === "ACTIVE")])
  );

  const [inboxPlan, links] = await Promise.all([
    findDomainInboxPlan(),
    loadDomainLinks(user.id, domains.map((d) => d.name)),
  ]);

  const active = domains.filter((d) => d.status === "ACTIVE").length;
  const expiring = domains.filter((d) => {
    if (d.status !== "ACTIVE") return false;
    const e = expiryState(d.expiresAt, now);
    return e.tone === "soon" || e.tone === "urgent";
  });
  const soonest = expiring
    .map((d) => expiryState(d.expiresAt, now).days!)
    .sort((a, b) => a - b)[0];
  const inProgress = domains.filter((d) => d.status === "TRANSFER_PENDING" || d.status === "PENDING").length;

  // What needs the customer's attention, most urgent first: expired domains,
  // and active ones expiring within 30 days with auto-renew switched off.
  const attention = domains
    .filter((d) => d.status === "EXPIRED" || (d.status === "ACTIVE" && !d.autoRenew && expiring.includes(d)))
    .slice(0, 3);

  const rows: DomainRow[] = domains.map((d) => ({
    id: d.id,
    name: d.name,
    status: d.status,
    expiresAtIso: d.expiresAt ? d.expiresAt.toISOString() : null,
    autoRenew: d.autoRenew,
    // An empty nameserver list means the domain is on our own DNS, which the
    // product calls Nxeon DNS; anything set is custom.
    nameserverLabel: d.nameservers.length === 0 ? "Nxeon DNS" : "Custom DNS",
    emailEnabled: emailByDomain.get(d.name) ?? false,
    priceCents: d.priceCents,
    renewCents: d.renewPriceCents ?? d.priceCents,
    link: links.get(d.name) ?? null,
  }));

  return (
    <>
      <DomainsAurora />

      {/* relative + z-1: DomainsAurora is a POSITIONED (fixed, z-0) layer, so
          it paints above ordinary static content. Lifting the content onto
          its own layer keeps it underneath. */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col">
        <DomainsHero
          title="Domains"
          sub="Search, register and transfer domains, then point them at your Nxeon services and manage DNS in one place."
        />

        {attention.length > 0 && (
          <div className="mt-1 space-y-2" role="region" aria-label="Domains that need attention">
            {attention.map((d) => {
              const e = expiryState(d.expiresAt, now);
              const expired = d.status === "EXPIRED" || e.tone === "expired";
              return (
                <Link
                  key={d.id}
                  href={`/dashboard/domains/${d.id}`}
                  className={
                    "flex flex-wrap items-center gap-x-3 gap-y-1 rounded-[14px] border px-4 py-3 text-[13px] transition hover:brightness-110 " +
                    (expired ? "border-rose/40 bg-rose/10" : "border-amber/40 bg-amber/10")
                  }
                >
                  <Icon name="warntriangle" size={15} tone="inherit" className={"flex-none " + (expired ? "text-rose" : "text-amber")} />
                  <span className="min-w-0 flex-1 text-tx">
                    <DomainName name={d.name} className="font-bold" />{" "}
                    {expired
                      ? <>has expired. Renew it before it&apos;s released so you keep the name.</>
                      : <>expires {e.text} and auto-renew is off.</>}
                  </span>
                  <span className={"font-semibold " + (expired ? "text-rose" : "text-amber")}>{expired ? "Renew →" : "Review →"}</span>
                </Link>
              );
            })}
          </div>
        )}

        <div className="mt-4 grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
          <div className="min-w-0 space-y-6">
            <DomainFinder configured={configured} sandbox={SANDBOX} />

            {domains.length > 0 && (
              <div className="card grid grid-cols-2 overflow-hidden rounded-[16px] p-0 sm:grid-cols-4">
                {[
                  <Figure key="a" value={domains.length} label="Domains" />,
                  <Figure key="b" value={active} label="Active" tone="mint" />,
                  <Figure
                    key="c"
                    value={expiring.length}
                    label="Expiring in 30 days"
                    tone={expiring.length ? "amber" : "tx"}
                    note={expiring.length ? `next in ${soonest} day${soonest === 1 ? "" : "s"}` : undefined}
                  />,
                  <Figure key="d" value={inProgress} label="Registering or transferring" tone={inProgress ? "cyan" : "tx"} />,
                ].map((f, i) => (
                  <div
                    key={i}
                    className={
                      "border-rim-soft " +
                      (i % 2 === 0 ? "border-r " : "") +
                      (i < 2 ? "border-b sm:border-b-0 " : "") +
                      (i === 1 ? "sm:border-r " : "") +
                      (i === 2 ? "sm:border-r " : "")
                    }
                  >
                    {f}
                  </div>
                ))}
              </div>
            )}

            <DomainsTabs
              mineCount={domains.length}
              mine={<DomainsTable rows={rows} configured={configured || SANDBOX} now={now} />}
              transfers={
                canTransfer ? (
                  <DomainTransferInWizard initialDomain="" balanceCents={user.balanceCents} />
                ) : (
                  <div className="card rounded-[16px] px-5 py-10 text-center text-[13.5px] text-tx-dim">
                    Transfers aren&apos;t switched on for your account yet. Domains already on your account stay fully manageable.
                  </div>
                )
              }
              ideas={<DomainIdeaGenerator configured={configured} />}
            />
          </div>

          <aside className="space-y-4">
            <div className="card relative overflow-hidden rounded-[16px] p-5">
              <span aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-[3px] bg-[linear-gradient(90deg,var(--color-blue),var(--color-violet),var(--color-brand-c))]" />
              <span className="grid h-11 w-11 place-items-center rounded-[12px] border border-violet/35 bg-violet/10">
                <Icon name="envelope" size={18} tone="inherit" className="text-violet" />
              </span>
              <h3 className="mt-3.5 text-[16px] font-extrabold text-white">Free business email</h3>
              <p className="mt-1.5 text-[13px] leading-relaxed text-tx-dim">
                Every domain you register comes with a free inbox
                {inboxPlan ? `: ${inboxPlan.mailboxes} mailbox, ${inboxPlan.storageGB} GB` : ""}.
              </p>
              <ul className="mt-3.5 space-y-2">
                {["you@yourdomain address", "Webmail on any device", "Spam protection"].map((f) => (
                  <li key={f} className="flex items-center gap-2 text-[13px] text-tx">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="flex-none text-mint" aria-hidden>
                      <path d="M20 6 9 17l-5-5" />
                    </svg>
                    {f}
                  </li>
                ))}
              </ul>
              <Link href="/dashboard/email" className="btn-secondary mt-4 w-full justify-center text-[12.5px]">Set up email</Link>
            </div>

            {canTransfer && (
              <Link href="/dashboard/domains/transfer" className="card group block overflow-hidden rounded-[16px] p-0 transition hover:border-violet/50">
                <span className="block bg-well/60 px-6 pt-2"><DomainTransferArt className="h-auto w-full" /></span>
                <span className="block p-4 pt-3">
                  <span className="flex items-center gap-2">
                    <span className="text-[15px] font-extrabold text-white">Transfer a domain in</span>
                    <span className="ml-auto text-tx-dim transition group-hover:translate-x-0.5" aria-hidden>→</span>
                  </span>
                  <span className="mt-1 block text-[12.5px] leading-snug text-tx-dim">
                    Bring a domain you own elsewhere. It keeps working while it moves, and a year is added.
                  </span>
                </span>
              </Link>
            )}

            <div className="card rounded-[16px] p-5">
              <h3 className="text-[15px] font-extrabold text-white">Need help?</h3>
              <div className="mt-2.5 space-y-0.5">
                {HELP_LINKS.map((item) => (
                  <Link
                    key={item.t}
                    href={item.href}
                    className="group -mx-1.5 flex items-center gap-3 rounded-[10px] px-1.5 py-2 transition hover:bg-hover"
                  >
                    <Icon name={item.icon} size={15} tone="inherit" className="flex-none text-blue" />
                    <span className="min-w-0 flex-1">
                      <span className="block text-[13px] font-semibold text-white">{item.t}</span>
                      <span className="block text-[11.5px] text-tx-faint">{item.s}</span>
                    </span>
                    <span className="text-tx-faint transition group-hover:translate-x-0.5 group-hover:text-white" aria-hidden>→</span>
                  </Link>
                ))}
              </div>
            </div>
          </aside>
        </div>
      </div>
    </>
  );
}

