"use client";

import { useState, useTransition } from "react";
import {
  setRedirect,
  deleteRedirect,
  setRegistrarLock,
  type Redirect,
  type RedirectsView,
  type LockView,
} from "@/lib/actions-domains-dns";
import { Badge } from "@/components/ui/primitives";

const TYPE_LABEL: Record<string, string> = {
  redirect301: "Permanent (301)",
  redirect302: "Temporary (302)",
  masked: "Masked (framed)",
};

export function DomainRedirects({
  domainId,
  domainName,
  initial,
}: {
  domainId: string;
  domainName: string;
  initial: RedirectsView;
}) {
  const [view, setView] = useState<RedirectsView>(initial);
  const [host, setHost] = useState<"" | "www">("");
  const [target, setTarget] = useState("");
  const [type, setType] = useState("redirect301");
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(initial.note ?? null);
  const [pending, start] = useTransition();

  function submit() {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setRedirect(domainId, host, target, type);
      if (res.error) setError(res.error);
      else {
        setView(res);
        setNote(res.note ?? "Saved.");
        setTarget("");
      }
    });
  }

  function remove(h: string) {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await deleteRedirect(domainId, h);
      if (res.error) setError(res.error);
      else {
        setView(res);
        setNote(res.note ?? "Removed.");
      }
      )}
    </div>
  );
}

/* -------------------------------------------------------------------------- *
 * Registrar lock — protects the domain against unauthorized transfers.
 * -------------------------------------------------------------------------- */

export function RegistrarLockCard({
  domainId,
  initial,
}: {
  domainId: string;
  initial: LockView;
}) {
  const [locked, setLocked] = useState(initial.locked);
  const [live, setLive] = useState(initial.live);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function toggle() {
    const next = !locked;
    setLocked(next); // optimistic
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setRegistrarLock(domainId, next);
      if (res.error) {
        setLocked(!next);
        setError(res.error);
      } else {
        setLocked(res.locked);
        setLive(res.live);
        setNote(res.note ?? "Saved.");
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Transfer lock</h2>
        <button
          type="button"
          role="switch"
          aria-checked={locked}
          aria-label="Transfer lock"
          disabled={pending}
          onClick={toggle}
          title={locked ? "Locked — click to unlock" : "Unlocked — click to lock"}
          className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400 disabled:opacity-50 ${
            locked ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
          }`}
        >
          <span
            className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
              locked ? "left-[18px]" : "left-0.5"
            }`}
          />
        </button>
      </div>
      <p className="text-sm text-slate-400">
        When locked, the domain can&apos;t be transferred to another registrar without first unlocking it —
        a strong defence against domain hijacking. Unlock only when you&apos;re starting a transfer out.
      </p>
      <p className="mt-2 text-xs text-slate-500">
        Currently <span className="font-medium text-slate-300">{locked ? "locked" : "unlocked"}</span>
        {live ? " (live)" : " (saved — applies once the domain is active)"}.
      </p>
      {note && <p className="mt-3 text-sm text-emerald-400">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}

