        <p className="mt-1.5 text-[12px] text-tx-faint">{HINT[type]}</p>
      </div>

      <div className="grid gap-3 sm:grid-cols-[minmax(0,180px)_minmax(0,1fr)]">
        <div>
          <label className="label" htmlFor="dns-name">Name</label>
          <div className={"flex h-10 items-center overflow-hidden rounded-[10px] border bg-well focus-within:border-violet " + (showErr && check.field === "name" ? "border-rose/60" : "border-rim-hi")}>
            <input
              id="dns-name"
              className="h-full min-w-0 flex-1 bg-transparent px-3 font-mono text-[13px] text-white outline-none placeholder:text-tx-faint"
              name="name"
              placeholder="@"
              autoComplete="off"
              autoCapitalize="none"
              spellCheck={false}
              value={name}
              onChange={(e) => setName(e.target.value)}
              aria-invalid={showErr && check.field === "name" ? true : undefined}
            />
          </div>
          <p className="mt-1 text-[11.5px] text-tx-faint">@ is the bare domain</p>
        </div>
        <div>
          <label className="label" htmlFor="dns-value">Value</label>
          <input
            id="dns-value"
            className={"input font-mono text-[13px] " + (showErr && check.field === "value" ? "!border-rose/60" : "")}
            name="address"
            placeholder={PLACEHOLDER[type] ?? "value"}
            autoComplete="off"
            autoCapitalize="none"
            spellCheck={false}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onBlur={() => value && setTouched(true)}
            aria-invalid={showErr && check.field === "value" ? true : undefined}
            aria-describedby="dns-check"
          />
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        {needsPriority && (
          <div>
            <label className="label" htmlFor="dns-prio">Priority</label>
            <input
              id="dns-prio"
              className={"input " + (showErr && check.field === "priority" ? "!border-rose/60" : "")}
              name="mxPref"
              type="number"
              inputMode="numeric"
              min={0}
              max={65535}
              value={priority}
              onChange={(e) => setPriority(e.target.value)}
            />
          </div>
        )}
        <div>
          <label className="label" htmlFor="dns-ttl">TTL</label>
          <select id="dns-ttl" className="input" name="ttl" defaultValue={1800}>
            {TTL_PRESETS.map(([v, label]) => (
              <option key={v} value={v}>{label}</option>
            ))}
          </select>
        </div>
      </div>

      <div id="dns-check" aria-live="polite" className="rounded-[11px] border border-rim bg-well px-3.5 py-2.5 text-[12.5px]">
        {showErr ? (
          <span className="flex items-start gap-2 text-rose">
            <Icon name="warntriangle" size={13} tone="inherit" className="mt-0.5 flex-none" />
            {check.error}
          </span>
        ) : value.trim() && check.ok ? (
          <span className="flex items-start gap-2 text-tx">
            <Icon name="checkcircle" size={13} tone="inherit" className="mt-0.5 flex-none text-mint" />
            <span className="min-w-0 break-words">{describeRecord(type, name, value, domainName)}</span>
          </span>
        ) : (
          <span className="text-tx-faint">
            This record will answer for <span className="font-mono text-tx-dim">{fqdnFor(name, domainName)}</span>
          </span>
        )}
      </div>

      <div className="flex flex-wrap items-center justify-end gap-2.5">
        {onDone && (
          <button type="button" onClick={onDone} className="btn-ghost text-[13px]">Cancel</button>
        )}
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add record"}
        </button>
      </div>
      {state?.error && (
        <div role="alert" className="rounded-[11px] border border-rose/35 bg-rose/10 px-3.5 py-2.5 text-[13px] text-rose">
          {state.error}
        </div>
      )}
    </form>
  );
}

/**
 * The DNS records table and its add form. Filter by type, read each record as
 * a sentence ("Mail for example.com goes to …"), and add records with the
 * value checked as you type. Every change still goes through the existing
 * server actions, which validate again before anything is published.
 */
export function DnsRecordsPanel({
  domainId,
  domainName,
  hosts,
  onCustomNameservers,
}: {
  domainId: string;
  domainName: string;
  hosts: DnsHost[];
  onCustomNameservers: boolean;
}) {
  const [filter, setFilter] = useState<string>("ALL");
  const [adding, setAdding] = useState(hosts.length === 0);
  const types = useMemo(() => [...new Set(hosts.map((h) => h.type))].sort(), [hosts]);
  const shown = filter === "ALL" ? hosts : hosts.filter((h) => h.type === filter);

  return (
    <section className="card p-0" aria-labelledby="dns-h">
      <div className="flex flex-wrap items-center gap-3 px-4 pt-5 sm:px-5">
        <div className="min-w-0 flex-1">
          <h2 id="dns-h" className="text-[16px] font-extrabold text-white">DNS records</h2>
          <p className="mt-0.5 text-[12.5px] text-tx-dim">{hosts.length} record{hosts.length === 1 ? "" : "s"} on Nxeon DNS</p>
        </div>
        <button type="button" onClick={() => setAdding((v) => !v)} aria-expanded={adding} className={adding ? "btn-secondary text-[13px]" : "btn-primary text-[13px]"}>
          {adding ? "Close" : "+ Add record"}
        </button>
      </div>

      {onCustomNameservers && (
        <p className="mx-4 mt-3 flex items-start gap-2 rounded-[11px] border border-amber/35 bg-amber/10 px-3.5 py-2.5 text-[12.5px] text-amber sm:mx-5">
          <Icon name="warntriangle" size={13} tone="inherit" className="mt-0.5 flex-none" />
          This domain uses custom nameservers, so the records below aren&apos;t live. Edit DNS at your other host, or switch back to Nxeon DNS.
        </p>
      )}

      {adding && (
        <div className="mx-4 mt-4 rounded-[14px] border border-violet/30 bg-well/60 p-4 sm:mx-5">
          <AddRecordForm domainId={domainId} domainName={domainName} onDone={hosts.length ? () => setAdding(false) : undefined} />
        </div>
      )}

      {hosts.length > 0 && (
        <div className="mt-4 flex gap-1.5 overflow-x-auto px-4 pb-1 sm:px-5" role="group" aria-label="Filter by record type">
          {["ALL", ...types].map((t) => {
            const n = t === "ALL" ? hosts.length : hosts.filter((h) => h.type === t).length;
            const on = filter === t;
            return (
              <button
                key={t}
                type="button"
                aria-pressed={on}
                onClick={() => setFilter(t)}
                className={"flex-none rounded-full border px-3 py-1 text-[12px] font-semibold transition " + (on ? "border-violet/60 bg-violet/15 text-white" : "border-rim bg-well text-tx-dim hover:text-white")}
              >
                {t === "ALL" ? "All" : t} <span className="text-tx-faint">{n}</span>
              </button>
            );
          })}
        </div>
      )}

      {hosts.length === 0 ? (
        <p className="px-5 pb-6 pt-4 text-[13px] text-tx-dim">No records yet. Start with a template above, or add your first record.</p>
      ) : (
        <>
          <div className="mt-3 hidden md:block">
            <table className="w-full table-fixed border-collapse text-left">
              <colgroup>
                <col className="w-[92px]" />
                <col className="w-[22%]" />
                <col />
                <col className="w-[84px]" />
                <col className="w-[96px]" />
              </colgroup>
              <thead>
                <tr className="border-y border-rim-soft text-[10.5px] uppercase tracking-[0.12em] text-tx-faint">
                  <th className="py-2.5 pl-5 font-bold">Type</th>
                  <th className="py-2.5 pr-4 font-bold">Name</th>
                  <th className="py-2.5 pr-4 font-bold">Value</th>
                  <th className="py-2.5 pr-4 font-bold">TTL</th>
                  <th className="py-2.5 pr-5"><span className="sr-only">Actions</span></th>
                </tr>
              </thead>
              <tbody>
                {shown.map((h, i) => (
                  <tr key={`${h.type}-${h.name}-${h.address}-${i}`} className="border-b border-rim-soft align-top last:border-0 hover:bg-hover">
                    <td className="py-3 pl-5"><TypeChip type={h.type} /></td>
                    <td className="py-3 pr-4">
                      <span className="block truncate font-mono text-[13px] font-semibold text-white" title={fqdnFor(h.name, domainName)}>{h.name}</span>
                    </td>
                    <td className="min-w-0 py-3 pr-4">
                      <span className="block truncate font-mono text-[12.5px] text-tx" title={h.address}>
                        {(h.type === "MX" || h.type === "SRV") && h.mxPref !== undefined && (
                          <span className="mr-1.5 rounded-[5px] bg-rim-soft px-1 text-[11px] text-tx-dim" title="Priority">{h.mxPref}</span>
                        )}
                        {h.address}
                      </span>
                      <span className="mt-0.5 block truncate text-[11.5px] text-tx-faint">{describeRecord(h.type, h.name, h.address, domainName)}</span>
                    </td>
                    <td className="py-3 pr-4 text-[12.5px] text-tx-dim">{ttlLabel(h.ttl)}</td>
                    <td className="py-3 pr-5 text-right">
                      <DnsDeleteButton domainId={domainId} record={{ name: h.name, type: h.type, address: h.address }} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <ul className="mt-3 space-y-2 px-3 pb-4 md:hidden">
            {shown.map((h, i) => (
              <li key={`${h.type}-${h.name}-${h.address}-${i}`} className="rounded-[13px] border border-rim bg-well p-3">
                <div className="flex items-center gap-2.5">
                  <TypeChip type={h.type} />
                  <span className="min-w-0 flex-1 truncate font-mono text-[13px] font-semibold text-white">{h.name}</span>
                  <span className="text-[11.5px] text-tx-faint">{ttlLabel(h.ttl)}</span>
                </div>
                <p className="mt-2 break-all font-mono text-[12.5px] text-tx">
                  {(h.type === "MX" || h.type === "SRV") && h.mxPref !== undefined && <span className="mr-1.5 text-tx-dim">{h.mxPref}</span>}
                  {h.address}
                </p>
                <div className="mt-2 flex items-center justify-between gap-2">
                  <span className="min-w-0 truncate text-[11.5px] text-tx-faint">{describeRecord(h.type, h.name, h.address, domainName)}</span>
                  <DnsDeleteButton domainId={domainId} record={{ name: h.name, type: h.type, address: h.address }} />
                </div>
              </li>
            ))}
          </ul>
        </>
      )}
    </section>
  );
}

