"use client";

import { useRef, useState, type KeyboardEvent } from "react";
import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { DomainAutoRenewToggle, RenewDomainButton } from "@/components/customer/DomainControls";
import { NameserversSection, WhoisPrivacySection, TransferSection } from "@/components/customer/DomainAdvanced";
import { DnsQuickSetup, DnsImportExportReset, type QuickServer } from "@/components/customer/DnsQuickSetup";
import { DomainRedirects, RegistrarLockCard } from "@/components/customer/DomainRedirects";
import { DomainChecklist, type ChecklistItem } from "@/components/customer/DomainChecklist";
import { DnsRecordsPanel } from "@/components/customer/domains/DnsRecordsPanel";
import { ExpiryMeter, Pill, expiryTone, fmtDate, type Tone } from "@/components/customer/domains/DomainBits";
import type { ExpiryState } from "@/lib/nx/domain-lifecycle";
import type { DnsHost } from "@/lib/registrar";
import type { LockView, RedirectsView } from "@/lib/actions-domains-dns";

/** One line of a label / value list: read-only facts, not controls. */
function InfoRow({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-4 border-b border-rim-soft py-2.5 last:border-0">
      <dt className="text-[12.5px] text-tx-dim">{label}</dt>
      <dd className="min-w-0 truncate text-right text-[13px] font-semibold text-white">{children}</dd>
    </div>
  );
}

function OnOff({ on, onText = "On", offText = "Off" }: { on: boolean; onText?: string; offText?: string }) {
  return <Pill tone={on ? "mint" : "slate"}>{on ? onText : offText}</Pill>;
}

const TABS = [
  { key: "overview", label: "Overview", icon: "globe2" },
  { key: "dns", label: "DNS records", icon: "server2" },
  { key: "nameservers", label: "Nameservers", icon: "globe3" },
  { key: "redirects", label: "Redirects", icon: "swap" },
  { key: "security", label: "Security", icon: "shieldcheck" },
  { key: "settings", label: "Transfer out", icon: "gear" },
] as const;
type TabKey = (typeof TABS)[number]["key"];

export function DomainDetailShell({
  domain,
  active,
  statusLabel,
  statusTone,
  expiry,
  term,
  renewPerYearCents,
  renewTotal,
  firstYearCents,
  checklist,
  registrarConfigured,
  quickServers,
  publicIp,
  dnsHosts,
  dnsError,
  redirectsView,
  lockView,
  hasEpp,
}: {
  domain: {
    id: string; name: string; status: string; registeredAt: string | null;
    expiresAt: string | null; autoRenew: boolean; whoisPrivacy: boolean; nameservers: string[];
  };
  active: boolean;
  statusLabel: string;
  statusTone: Tone;
  expiry: ExpiryState;
  term: { label: string; years: number };
  renewPerYearCents: number;
  renewTotal: number;
  /** What the first year cost, to flag a higher renewal price up front. */
  firstYearCents: number;
  checklist: ChecklistItem[];
  registrarConfigured: boolean;
  quickServers: QuickServer[];
  publicIp: string;
  dnsHosts: DnsHost[] | null;
  dnsError: string | null;
  redirectsView: RedirectsView;
  lockView: LockView;
  hasEpp: boolean;
}) {
  const [tab, setTab] = useState<TabKey>("overview");
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});
  const customNs = domain.nameservers.length > 0;
  const renewTone = expiryTone(expiry);
  const done = checklist.filter((c) => c.done).length;

  const go = (k: TabKey) => {
    setTab(k);
    requestAnimationFrame(() => document.getElementById("domain-tabs")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  };

  const onKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    let next = -1;
    if (e.key === "ArrowRight") next = (i + 1) % TABS.length;
    if (e.key === "ArrowLeft") next = (i - 1 + TABS.length) % TABS.length;
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = TABS.length - 1;
    if (next < 0) return;
    e.preventDefault();
    setTab(TABS[next].key);
    refs.current[TABS[next].key]?.focus();
  };

  return (
    <div className="space-y-5">
      <div id="domain-tabs" role="tablist" aria-label="Domain sections" className="flex scroll-mt-4 gap-6 overflow-x-auto border-b border-rim-soft">
        {TABS.map((t, i) => (
          <button
            key={t.key}
            ref={(el) => { refs.current[t.key] = el; }}
            type="button"
            role="tab"
            id={`dtab-${t.key}`}
            aria-selected={tab === t.key}
            aria-controls={`dpanel-${t.key}`}
            tabIndex={tab === t.key ? 0 : -1}
            data-tour={`tab-${t.key}`}
            onClick={() => setTab(t.key)}
            onKeyDown={(e) => onKey(e, i)}
            className={"nx-tab flex flex-none items-center gap-1.5 " + (tab === t.key ? "nx-tab-on" : "")}
          >
            <Icon name={t.icon} size={13} className={tab === t.key ? "" : "nx-ico-slate"} />
            {t.label}
          </button>
        ))}
      </div>

      <div role="tabpanel" id={`dpanel-${tab}`} aria-labelledby={`dtab-${tab}`}>
        {tab === "overview" && (
          <div className="grid gap-4 lg:grid-cols-3">
            {/* Renewal — the money card, with the real renewal price up front. */}
            <section id="renewal-billing" className="card scroll-mt-4 p-5 lg:col-span-1" aria-labelledby="ren-h">
              <div className="flex items-center justify-between gap-2">
                <h2 id="ren-h" className="text-[15px] font-extrabold text-white">Renewal</h2>
                {domain.expiresAt && (
                  <Pill tone={renewTone}>{expiry.tone === "expired" ? "Expired" : expiry.text}</Pill>
                )}
              </div>
              {domain.expiresAt ? (
                <>
                  <p className="mt-3 text-[12px] text-tx-faint">{expiry.tone === "expired" ? "Expired on" : "Renews on"}</p>
                  <p className="num text-[26px] leading-tight text-white" suppressHydrationWarning>{fmtDate(domain.expiresAt)}</p>
                  <ExpiryMeter state={expiry} className="mt-2.5" />
                  <div className="mt-4 rounded-[12px] border border-rim bg-well p-3.5">
                    <div className="flex items-baseline justify-between gap-2">
                      <span className="text-[12.5px] text-tx-dim">Renewal price</span>
                      <span className="text-right">
                        <span className="num text-[18px] text-white">{fmtMoney(renewTotal)}</span>
                        <span className="text-[12px] text-tx-faint"> / {term.label}</span>
                      </span>
                    </div>
                    {term.years > 1 && (
                      <p className="mt-1 text-right text-[11.5px] text-tx-faint">{fmtMoney(renewPerYearCents)}/yr before the multi-year discount</p>
                    )}
                    {renewPerYearCents > firstYearCents && (
                      <p className="mt-2 text-[11.5px] leading-snug text-tx-faint">
                        Your first year was {fmtMoney(firstYearCents)}. Renewals are charged at the regular rate shown here.
                      </p>
                    )}
                    <div className="mt-3 flex items-center justify-between gap-3 border-t border-rim-soft pt-3">
                      <span className="min-w-0">
                        <span className="block text-[13px] font-semibold text-white">Auto-renew</span>
                        <span className="block text-[11.5px] text-tx-faint">
                          {domain.autoRenew ? "Charged from your balance or card before it expires." : "Off. You'll need to renew by hand."}
                        </span>
                      </span>
                      <DomainAutoRenewToggle domainId={domain.id} autoRenew={domain.autoRenew} domainName={domain.name} />
                    </div>
                  </div>
                  {active && (
                    <div className="mt-3">
                      <RenewDomainButton domainId={domain.id} priceCents={renewPerYearCents} termYears={term.years} />
                    </div>
                  )}
                </>
              ) : (
                <p className="mt-3 text-[13px] leading-relaxed text-tx-dim">
                  The renewal date appears here once the domain is active.
                </p>
              )}
            </section>

            {/* Setup progress */}
            <div className="lg:col-span-1">
              <DomainChecklist items={checklist} onAction={(k) => go(k)} />
            </div>

            {/* Facts + quick links */}
            <section className="card p-5 lg:col-span-1" aria-labelledby="facts-h">
              <h2 id="facts-h" className="text-[15px] font-extrabold text-white">Details</h2>
              <dl className="mt-2">
                <InfoRow label="Status"><Pill tone={statusTone}>{statusLabel}</Pill></InfoRow>
                <InfoRow label="Registered">{domain.registeredAt ? <span suppressHydrationWarning>{fmtDate(domain.registeredAt)}</span> : "—"}</InfoRow>
                <InfoRow label="Registrar">Nxeon Domains</InfoRow>
                <InfoRow label="DNS">{customNs ? "Custom nameservers" : "Nxeon DNS"}</InfoRow>
                <InfoRow label="WHOIS privacy"><OnOff on={domain.whoisPrivacy} /></InfoRow>
                <InfoRow label="Transfer lock"><OnOff on={lockView.locked} onText="Locked" offText="Unlocked" /></InfoRow>
              </dl>
              <div className="mt-4 grid grid-cols-2 gap-2">
                {[
                  { k: "dns" as const, icon: "server2", t: "Edit DNS" },
                  { k: "nameservers" as const, icon: "globe3", t: "Nameservers" },
                  { k: "redirects" as const, icon: "swap", t: "Redirects" },
                  { k: "security" as const, icon: "shieldcheck", t: "Security" },
                ].map((a) => (
                  <button key={a.k} type="button" onClick={() => go(a.k)}
                          className="flex items-center gap-2 rounded-[11px] border border-rim bg-well px-3 py-2.5 text-left text-[12.5px] font-semibold text-tx-dim transition hover:border-violet/50 hover:text-white">
                    <Icon name={a.icon} size={13} tone="inherit" className="flex-none text-violet" />
                    {a.t}
                  </button>
                ))}
              </div>
            </section>
          </div>
        )}

        {tab === "dns" && (
          <div className="space-y-5">
            {!active ? (
              <div className="card p-6 text-[13.5px] text-tx-dim">DNS management opens once the domain is active.</div>
            ) : dnsError ? (
              <div className="card p-5">
                <div role="alert" className="rounded-[12px] border border-amber/35 bg-amber/10 px-4 py-3">
                  <p className="text-[13px] text-amber">We couldn&apos;t load the DNS records: {dnsError}</p>
                  <p className="mt-1 text-[12px] text-tx-faint">Lookups are sometimes briefly unavailable. Refresh to try again.</p>
                </div>
              </div>
            ) : dnsHosts ? (
              <>
                <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
                  <DnsRecordsPanel domainId={domain.id} domainName={domain.name} hosts={dnsHosts} onCustomNameservers={customNs} />
                  <DnsQuickSetup domainId={domain.id} domainName={domain.name} servers={quickServers} publicIp={publicIp} />
                </div>
                <details className="group">
                  <summary className="flex cursor-pointer list-none items-center gap-2 text-[13px] font-semibold text-tx-dim hover:text-white">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="transition-transform group-open:rotate-90"><path d="m9 6 6 6-6 6" /></svg>
                    Import, export and reset
                  </summary>
                  <div className="mt-3"><DnsImportExportReset domainId={domain.id} publicIp={publicIp} /></div>
                </details>
              </>
            ) : (
              <div className="card p-6 text-[13.5px] text-tx-dim">DNS isn&apos;t available for this domain right now.</div>
            )}
          </div>
        )}

        {tab === "nameservers" && (
          <NameserversSection domainId={domain.id} initial={domain.nameservers} active={active} registrarReady={registrarConfigured} />
        )}

        {tab === "redirects" && (
          <DomainRedirects domainId={domain.id} domainName={domain.name} initial={redirectsView} />
        )}

        {tab === "security" && (
          <div className="grid gap-5 lg:grid-cols-2">
            <WhoisPrivacySection domainId={domain.id} initial={domain.whoisPrivacy} />
            <RegistrarLockCard domainId={domain.id} initial={lockView} />
          </div>
        )}

        {tab === "settings" && (
          <TransferSection domainId={domain.id} active={active} hasEpp={hasEpp} />
        )}
      </div>
      <p className="sr-only" aria-live="polite">{`${done} of ${checklist.length} setup steps done`}</p>
    </div>
  );
}

