"use client";

export type ChecklistTab = "dns" | "nameservers" | "redirects" | "security" | "settings";
export type ChecklistItem = {
  label: string;
  done: boolean;
  hint?: string;
  /** The detail-page tab that fixes this item, for the inline "Set up" link. */
  tab?: ChecklistTab;
};

/**
 * How "set up" a domain is: a progress ring and the steps, each unfinished one
 * with a link to the tab that finishes it. Presentational — the page computes
 * the items from the domain, its DNS records and the customer's servers.
 */
export function DomainChecklist({ items, onAction }: { items: ChecklistItem[]; onAction?: (tab: ChecklistTab) => void }) {
  const done = items.filter((i) => i.done).length;
  const pct = items.length ? done / items.length : 0;
  const complete = done === items.length;
  const r = 22, c = 2 * Math.PI * r;

  return (
    <section className="card h-full p-5" aria-labelledby="setup-h">
      <div className="flex items-center gap-4">
        <svg width="56" height="56" viewBox="0 0 56 56" className="flex-none -rotate-90" aria-hidden>
          <defs>
            <linearGradient id="nx-setup-ring" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" style={{ stopColor: "var(--color-blue)" }} />
              <stop offset="1" style={{ stopColor: complete ? "var(--color-mint)" : "var(--color-violet)" }} />
            </linearGradient>
          </defs>
          <circle cx="28" cy="28" r={r} fill="none" strokeWidth="5" style={{ stroke: "var(--color-rim-soft)" }} />
          <circle cx="28" cy="28" r={r} fill="none" strokeWidth="5" strokeLinecap="round" stroke="url(#nx-setup-ring)"
                  strokeDasharray={`${c * pct} ${c}`} className="transition-all duration-500" />
        </svg>
        <div className="min-w-0">
          <h2 id="setup-h" className="text-[15px] font-extrabold text-white">Setup</h2>
          <p className="text-[12.5px] text-tx-dim">
            {complete ? "This domain is fully set up." : `${done} of ${items.length} done`}
          </p>
        </div>
      </div>

      <ul className="mt-4 space-y-1">
        {items.map((item) => (
          <li key={item.label} className="flex items-start gap-3 rounded-[10px] py-1.5">
            <span
              aria-hidden
              className={
                "mt-0.5 grid h-5 w-5 flex-none place-items-center rounded-full border " +
                (item.done ? "border-mint/50 bg-mint/15 text-mint" : "border-rim-hi bg-well")
              }
            >
              {item.done && (
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5" /></svg>
              )}
            </span>
            <span className="min-w-0 flex-1">
              <span className={"block text-[13px] " + (item.done ? "text-tx-dim" : "font-semibold text-white")}>
                {item.label}
                <span className="sr-only">{item.done ? " (done)" : " (to do)"}</span>
              </span>
              {!item.done && item.hint && <span className="block text-[12px] leading-snug text-tx-faint">{item.hint}</span>}
            </span>
            {!item.done && item.tab && onAction && (
              <button type="button" onClick={() => onAction(item.tab!)} className="flex-none text-[12px] font-semibold text-violet hover:underline">
                Set up
              </button>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}

