import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import {
  getDnsHosts,
  registrarConfigured,
  registrarSafeMessage,
  sandboxDnsActive,
  transferStatusLabel,
  type DnsHost,
} from "@/lib/registrar";
import { transferChargeCents } from "@/lib/domain-transfer";
import { TransferInStatusCard } from "@/components/customer/DomainTransferIn";
import { getRegistrarLock, listRedirects } from "@/lib/actions-domains-dns";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { DomainsAurora } from "@/components/nx/DomainsAurora";
import { DomainPendingArt } from "@/components/nx/visual/DomainArt";
import type { QuickServer } from "@/components/customer/DnsQuickSetup";
import { DomainDetailShell } from "@/components/customer/DomainDetailShell";
import { type ChecklistItem } from "@/components/customer/DomainChecklist";
import { DomainName, Pill, fmtDate, statusMeta } from "@/components/customer/domains/DomainBits";
import { DomainTour } from "@/components/nx/tour/DomainTour";
import { expiryState } from "@/lib/nx/domain-lifecycle";

export const dynamic = "force-dynamic";

export default async function DomainPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ new?: string }>;
}) {
  const { id } = await params;
  const { new: justRegistered } = await searchParams;
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();

  const publicIp = process.env.PUBLIC_IP ?? "";
  const active = domain.status === "ACTIVE";
  const showGoLive = justRegistered === "1" && active;
  const now = Date.now();

  // The user's own servers — targets for the "point at my server" template.
  const servers = await db.server.findMany({
    where: { userId: domain.userId },
    include: { dedicatedIp: true, node: { select: { publicIp: true } } },
    orderBy: { createdAt: "desc" },
  });
  const quickServers: QuickServer[] = servers.map((s) => ({
    id: s.id,
    label: s.label || s.name || s.hostname,
    ip: s.dedicatedIp?.address || s.node?.publicIp || "",
  }));

  let dnsHosts: DnsHost[] | null = null;
  let dnsError: string | null = null;
  // sandboxDnsActive(): a no-credentials sandbox box reads an in-memory zone
  // instead of a registrar, so the editor can be reviewed. Never on staging/prod.
  if (active && (registrarConfigured() || sandboxDnsActive())) {
    try {
      dnsHosts = await getDnsHosts(domain.name);
    } catch (e) {
      dnsError = registrarSafeMessage(e);
    }
  }

  const [lockView, redirectsView] = await Promise.all([
    getRegistrarLock(domain.id),
    listRedirects(domain.id),
  ]);

  let hostingFromCents: number | null = null;
  let vpsFromCents: number | null = null;
  if (showGoLive) {
    const [hostingPlans, vpsPlans] = await Promise.all([
      db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }),
      db.plan.findMany({ where: { active: true }, select: { priceCents: true } }),
    ]);
    hostingFromCents = hostingPlans.length ? Math.min(...hostingPlans.map((p) => p.priceCents)) : null;
    vpsFromCents = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
  }

  // ----- Setup checklist -----
  const knownIps = new Set<string>([publicIp, ...quickServers.map((s) => s.ip)].filter(Boolean));
  const apexRecords = (dnsHosts ?? []).filter((h) => h.name === "@" || h.name === "www");
  const pointedAtServer = apexRecords.some(
    (h) => (h.type === "A" && knownIps.has(h.address)) || h.type === "CNAME" || h.type === "ALIAS"
  );
  const emailConfigured = (dnsHosts ?? []).some((h) => h.type === "MX");
  const checklist: ChecklistItem[] = [
    {
      label: domain.isTransferIn ? "Domain transferred in" : "Domain registered",
      done: active,
      hint: domain.isTransferIn
        ? "The transfer is still running. Approve the confirmation email from your old registrar."
        : "Registration is still processing.",
    },
    { label: "Pointed at a server", done: pointedAtServer, hint: "Use the “Point to my Nxeon server” template.", tab: "dns" },
    { label: "Email set up", done: emailConfigured, hint: "Add MX records with a template, or from your mail host.", tab: "dns" },
    { label: "WHOIS privacy on", done: domain.whoisPrivacy, hint: "Keeps your contact details out of public records.", tab: "security" },
    { label: "Auto-renew on", done: domain.autoRenew, hint: "Turn it on in the Renewal card so the domain never lapses." },
  ];

  const meta = statusMeta(domain.status);
  const term = domainTerm(domain.termYears);
  const renewPerYearCents = domain.renewPriceCents ?? domain.priceCents;
  const renewTotal = domainTermPriceCents(renewPerYearCents, term.years);
  const expiry = expiryState(domain.expiresAt, now);

  return (
    <>
      <DomainsAurora />

      {/* No full-screen Provisioning takeover, deliberately: registration is
          synchronous, so there is no real multi-step progress to show, and each
          of PENDING / FAILED / just-registered has its own inline banner. */}
      {domain.status === "PENDING" && <AutoRefresh />}

      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col">
        <header className="pt-2">
          <Link
            href="/dashboard/domains"
            className="inline-flex items-center gap-1.5 text-[12.5px] font-semibold text-tx-dim transition hover:text-tx"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M15 18l-6-6 6-6" />
            </svg>
            All domains
          </Link>
          <div className="mt-3 flex flex-wrap items-end justify-between gap-x-6 gap-y-4">
            <div className="min-w-0">
              <span className="block text-[11px] font-extrabold uppercase tracking-[0.24em] text-[#f21cff]">Domain</span>
              <h1 className="mt-1.5 break-all text-[30px] font-extrabold leading-[1.05] tracking-[-0.035em] text-white sm:text-[40px]">
                <DomainName name={domain.name} />
              </h1>
              <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-2 text-[12.5px] text-tx-dim">
                <Pill tone={meta.tone} pulse={meta.pulse}>{meta.label}</Pill>
                {domain.registeredAt && <span suppressHydrationWarning>Registered {fmtDate(domain.registeredAt)}</span>}
                {domain.expiresAt && (
                  <span suppressHydrationWarning>
                    · {expiry.tone === "expired" ? "Expired" : "Renews"} {fmtDate(domain.expiresAt)}{" "}
                    <span className={expiry.tone === "ok" ? "" : expiry.tone === "soon" ? "font-semibold text-amber" : "font-semibold text-rose"}>({expiry.text})</span>
                  </span>
                )}
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <DomainTour domain={domain} />
              {active && (
                <a href={`https://${domain.name}`} target="_blank" rel="noreferrer" className="btn-secondary h-10 gap-1.5 px-4 text-[13px]">
                  Visit site
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d="M7 17 17 7M8 7h9v9" /></svg>
                  <span className="sr-only">(opens in a new tab)</span>
                </a>
              )}
            </div>
          </div>
        </header>

        <div className="mt-6 space-y-4">
          {showGoLive && (
            <section className="card relative overflow-hidden border-mint/35 p-5" aria-labelledby="golive-h">
              <span aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-[3px] bg-[linear-gradient(90deg,var(--color-mint),var(--color-cyan))]" />
              <div className="flex items-start gap-3">
                <span className="grid h-10 w-10 flex-none place-items-center rounded-full bg-mint/15 text-mint">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d="M20 6 9 17l-5-5" /></svg>
                </span>
                <div>
                  <h2 id="golive-h" className="text-[16px] font-extrabold text-white">{domain.name} is yours</h2>
                  <p className="mt-1 text-[13px] text-tx-dim">
                    Now put something on it. Add hosting or a VPS and point this domain at it in a couple of clicks.
                  </p>
                </div>
              </div>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                <div className="rounded-[13px] border border-rim bg-well p-4">
                  <p className="text-[14px] font-bold text-white">Shared web hosting</p>
                  <p className="mt-1 text-[12.5px] leading-relaxed text-tx-dim">
                    PHP, MySQL, free SSL and a free mailbox on this domain.
                    {hostingFromCents !== null && <> Plans from {fmtMoney(hostingFromCents)}/mo, first month free.</>}
                  </p>
                  <Link href="/web-hosting" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See hosting plans</Link>
                </div>
                <div className="rounded-[13px] border border-rim bg-well p-4">
                  <p className="text-[14px] font-bold text-white">NVMe VPS</p>
                  <p className="mt-1 text-[12.5px] leading-relaxed text-tx-dim">
                    Full root access for apps, game servers, or anything shared hosting can&apos;t run.
                    {vpsFromCents !== null && <> Plans from {fmtMoney(vpsFromCents)}/mo.</>}
                  </p>
                  <Link href="/vps" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See VPS plans</Link>
                </div>
              </div>
            </section>
          )}

          {domain.status === "FAILED" && (
            <div role="alert" className="flex items-start gap-3 rounded-[14px] border border-rose/40 bg-rose/10 px-4 py-3.5 text-[13px]">
              <span className="mt-0.5 h-2 w-2 flex-none rounded-full bg-rose" aria-hidden />
              <span className="text-tx">
                <span className="font-bold text-rose">Registration didn&apos;t go through</span>
                {domain.error ? `: ${domain.error}.` : "."} You were refunded. Try again, or{" "}
                <Link href="/dashboard/support" className="font-semibold text-violet hover:underline">contact support</Link>.
              </span>
            </div>
          )}

          {domain.status === "EXPIRED" && (
            <div role="alert" className="flex items-start gap-3 rounded-[14px] border border-rose/40 bg-rose/10 px-4 py-3.5 text-[13px]">
              <span className="mt-0.5 h-2 w-2 flex-none rounded-full bg-rose" aria-hidden />
              <span className="text-tx">
                <span className="font-bold text-rose">This domain has expired.</span> Its website and email may stop working.
                Expired domains can usually still be recovered for a short time,{" "}
                <Link href="/dashboard/support" className="font-semibold text-violet hover:underline">contact support</Link> and we&apos;ll help you renew it.
              </span>
            </div>
          )}

          {domain.status === "PENDING" && !domain.isTransferIn && (
            <div role="status" className="card flex items-center gap-4 border-cyan/35 p-4">
              <DomainPendingArt className="h-12 w-12 flex-none" />
              <div>
                <p className="text-[14px] font-bold text-white">Registering {domain.name}</p>
                <p className="mt-0.5 text-[12.5px] text-tx-dim">
                  This usually finishes within a minute. The page refreshes on its own.
                </p>
              </div>
            </div>
          )}

          {domain.isTransferIn && (domain.status === "TRANSFER_PENDING" || domain.status === "TRANSFER_FAILED") && (
            <TransferInStatusCard
              domainId={domain.id}
              domainName={domain.name}
              status={domain.status}
              transferStatus={domain.transferStatus}
              transferStatusLabel={domain.transferStatus ? transferStatusLabel(domain.transferStatus) : null}
              transferEmail={domain.transferEmail}
              transferStartedAt={domain.transferStartedAt ? domain.transferStartedAt.toISOString() : null}
              priceCents={transferChargeCents(domain.priceCents)}
              error={domain.error}
            />
          )}

          <DomainDetailShell
            domain={{
              id: domain.id,
              name: domain.name,
              status: domain.status,
              registeredAt: domain.registeredAt ? domain.registeredAt.toISOString() : null,
              expiresAt: domain.expiresAt ? domain.expiresAt.toISOString() : null,
              autoRenew: domain.autoRenew,
              whoisPrivacy: domain.whoisPrivacy,
              nameservers: domain.nameservers,
            }}
            active={active}
            statusLabel={meta.label}
            statusTone={meta.tone}
            expiry={expiry}
            term={term}
            renewPerYearCents={renewPerYearCents}
            renewTotal={renewTotal}
            firstYearCents={domain.priceCents}
            checklist={checklist}
            registrarConfigured={registrarConfigured()}
            quickServers={quickServers}
            publicIp={publicIp}
            dnsHosts={dnsHosts}
            dnsError={dnsError}
            redirectsView={redirectsView}
            lockView={lockView}
            hasEpp={!!domain.transferEpp}
          />
        </div>
      </div>
    </>
  );
}

